INSERT INTO Definition
(word_id,language_id,pos_id,definition,example)
VALUES
(2830,3,1,'တတိယမွန်ဗျည်း။',null)
,(2831,3,1,'၁။ လူမျိုး။','ဂကူမန် = မွန်လူမျိုး။ ဂကူဗၟာ = ဗမာလူမျိုး။')
,(2831,3,1,'၂။ အမျိုးအစား။','ကွဳစက်ဂကူတဝ်ယျဝ်တာ = တိုယိုတာအမျိုးအစားကား။')
,(2831,3,1,'၃။ မျိုးရိုး။ အနွယ်။','“ဗောဓိသတ်ပိုဲ ဒှ်ပ္ဍဲဂကူဗမၞး—။” (ဇ—၁၆၁။ အစွောံ။) = “ဘုရားလောင်းသည် ပုဏ္ဏားမျိုး­ဖြစ်၍—။” (ညောင်ကန်) || “ဗောဓိသတ်ပိုဲ ဒှ်ပ္ဍဲဂကူစဏာ—။” (ဇ—၁၇၉။ အစွောံ။) = “ဘုရားလောင်းသည် ဒွန်းစဏ္ဍားအမျိုး­ဖြစ်၍—။” (ညောင်ကန်)')
,(2832,3,1,'ဝမ်းကိုက်ခြင်း။','ယဲဂကိတ် = ဝမ်းကိုက်ရောဂါ။')
,(2833,3,1,'မှာခြင်း။ မှာကြားခြင်း။ အမှာ။','“လၟေၚ်ဂကန်မိမဂှ် ပဗက်တုဲ—။” (ဇ—၁၇၈။ အစွောံ။) = “မိဘအမှာစကားအတိုင်း လိုက်နာ၍—။”')
,(2833,3,4,'မှာသည်။ မှာကြားသည်။','“ဗမၞးဂကန်ကဵုကောန်တ္ၚေက်ၜါတုဲ အာသွံစရ။” (ဇ—၁၄၅။ အစွောံ။) = “ပုဏ္ဏားသည် ကျေးသား ညီနောင်တို့ကို မှာကြားပြီးနောက် ကုန်ရောင်းအံ့သောငှာသွား၏။” || “ယွံဇမၠိၚ်ဇကု သာ်ဝွံကော် အဲရ” ဇြုံဂကန်တုဲ စဍးအာရ။ (ဇ—၇၃။ အစွောံ။) = “အိုၚကိုယ်ရှည်ဟု အကျွန်ုပ်ကိုခေါ်ပါ လော့” ဟုမြွေသည်မှာ၍ သွား၏။ || “မိကဵုမဂကန်ကဵုကောန်တြုံရ။” (ဇ—၁၇၈။ အစွောံ။) = “မိခင်ဖခင်တို့သည် သားအားမှာကြား၏။” || ‘ဗကန်’ ဟုလည်း အရေးရှိသည်။')
,(2834,3,4,'မှာကြားသည်။ အမှာစကားပါးသည်။ သတင်းစကားပါးသည်။','“သမ္ဘာဂမှဳတံဂှ်ကီု လေဝ် ဒဒှ်ဂမှဳတံဂှ် ဟွံဂွံလှိၚ်စိုတ်ပ္ဍဲသာသၞာဂှ် ဍေံတံတီတုဲ ဍေံတံဂကန်ဖျန်ပ္တိတ်ကဵုဂမှဳတံဂှ်ရ။”(ဇ— ၅၃၆။ အစွောံ။) = “ထိုရဟန်းတို့၏မယားဟောင်းတို့သည်လည်း ထိုရဟန်းတို့ သာသနာတော်­ မမွေ့လျော်သောအဖြစ်ကို သိကြကုန်၍ ထိုရဟန်းတို့အား သတင်းစကား ပါးထုတ်ကြကုန်၏။” || “ဂကန်ဖျန် (ကဵုဣသိ) တုဲ သၟိၚ်ဍိုက်စိၚ်စဴအာရ။” (ဇ—၂၅၉။ အစွောံ။) = “မင်းသည် ရသေ့ကို မှာကြားပြီးလျှင် ဆင်စီး၍ပြန်သွား၏။” || ‘ဗကန်ဖျန်’ ဟုလည်းရေးသည်။')
,(2835,3,1,'အဖွဲ့အစည်း။ အသင်းအပင်း။ အတူစုရုံးခြင်း။','ဂကောံဝေယျာဝစ္စ = ဝေယျာဝစ္စအသင်း။ ဂကောံသၟတ်ဝုတ်ဗၠာဲ = အပျိုလူပျိုအသင်း။')
,(2835,3,5,'အတူ၊ နှင့်အတူ၊ အတူ တကွ။','“ဗှ်ေအာဂကောံအဲကီုဟာ” = “ငါနှင့်အတူ မင်းလိုက်မလား။” || “ယွံကောန်၊ ဂကောံ ဒြာဲနိဂြောဓဂှ်ဟေၚ် ဂပ်ဂဝ်သိပ်ဂၠိပိညိကောန်။ ဂကောံဒြာဲသာခဂှ် လ္ပသိပ်ဂၠိပ်ညိ။ ဂကောံဒြာဲထဝ် နိဂြောဓဂှ် ဗတ်ချိုတ်အာဂှ် ပြဲသန်ရ။ ဂကောံဒြာဲသာခဂှ် ကဵုဂျိုၚ်တဴလမျီုကီုရ ဟွံပြဲသက်သက် ဟေၚ်ရကောန်” ၝောံဒြာဲဂး။ (ဇ—၁၂။ အစွောံ။) = “ချစ်သား၊ နိဂြောဓသမင်ကိုသာလျှင် မှီဝဲရာ၏။ သာခသမင်ကို မမှီဝဲရာ။ နိဂြောဓသမင်နှင့်တကွ သေရခြင်းသည်လည်း ကောင်းမြတ်၏။ သာခသမင်နှင့်တကွ အသက်ရှင်ရခြင်းသည် မကောင်းမြတ်သည်သာလျှင်တည်း။”')
,(2836,3,4,'(ငြီးငွေ့၍ဖြစ်စေ၊ မမွေ့လျော်၍ဖြစ်စေ၊ တောင့်တ၍ဖြစ်စေ) ညည်းညူသည်။ ညည်းတွားသည်။ (ပါဠိ—နိတ္ထုန/အရတိ)','“သၟိၚ်ကွဴမဍုန်အာလတူဆုဂှ် လ္ပကဵုဒးဂကဝ်ဒၟံၚ်ညိဂး တုဲ ကွဴဝုတ်မသုန်ကၠံ မၞုံရမ်သာၚ်မမိပ် ရမျှာၚ်မဇိပ်ကၠိပ် ရမျှာၚ်မဍိုန်ညံတံဂှ် ကဵုဟီုဗက်အာကြဴကြဴ ဂှ်တုဲ ကဵုပဝ်ဗက်အာကြဴကြဴရ။” (ဇ—၅၃၆။ အစွောံ။) = “ငါးရာကုန်သော ဥသြငှက်မတို့သည် ပြေပြစ်ကုန်သော ချစ်ဖွယ်ရှိကုန်သော သာယာကုန်သော ချိုသာကုန်သော စကားတို့ဖြင့် ပြော ဟောကုန်လျက် ဤဥသြငှက်မင်းသည် နေရာ­ မမွေ့လျော်၍ညည်းညူခြင်း မရှိပါစေသတည်းဟု နှလုံးသွင်း၍ နောက်မှနောက်မှ ပျံသွားကုန်၏။” || “ပဟိုတ်ကဵုဂမှဳမွဲ သၟိက်ဂွံရာံ ဂကဝ်ဒၟံၚ်တုဲ မ ဟာမောရဇာတ် ကျာ်တြဲတွံ။” (ဇ—၄၉၁။ အစွောံ။)= “လူဝတ်လဲရန် ညည်းညူနေသောရဟန်း တပါးကို အကြောင်းပြု၍ မဟာမောရဇာတ်ကို မြတ်စွာဘုရားဟောကြားတော်မူသည်။” || “ယွံဒေံ၊ အဲဟွံလှိၚ်စိုတ် ပ္ဍဲသ္ၚိသၟိန်ဝွံသက်က်ရ။ ပ္ဍဲစိုတ်အဲဝွံဂှ် ညံၚ်စာၚ်ဂြိုပ် ညးကြိုၚ်လဝ်ဂှ်ကီုရ။ အဲဂကဝ်ဒၟံၚ် သၟိက်ဂွံပဂမှဳရောၚ်။” (ဇ—၅၂၅။ အစွောံ။) = “ငါ့ညီတော်၊ ငါသည် အိမ်ထောင်နေသော လူတို့ဘောင်­ လုံးဝမပျော်မွေ့ပြီ။ ငါ၏စိတ်­ ဆောင်းလှောင်သော တောကြက်ကဲ့သို့ဖြစ် ၏။ ငါသည် ရဟန်းပြုလို၍ တောင့်တညည်းညူနေပါသည်။”')
,(2837,3,1,'လည်ပျဉ်း။ (လည်ပင်းမှတွဲကျသော အသားအရေ)','ဂကဵုကအ်ဂၠဴ = နွားလည်ပျဉ်း။ (ပါဠိ—ဂလကမ္ဗလ)')
,(2838,3,4,'အချိုးအစားမကျအောင်ငယ်သည်။','ဂၞိၚ်ဂဂန် = အလွန်သေးငယ်သောခါး။')
,(2839,3,1,'ကင်းခြေများ။','“မပ္တံအယဴ၊ ဂဂဳ၊ စၟတသော်ဖိုၚ်ကၠတံဂှ်ကီု။” (ဇ—၂ဝ၃။ အစွောံ။) = “ကင်းမြီးကောက်၊ ကင်းခြေများ၊ (အမွေးထူ) ပင့်ကူကြီး စသည်တို့သည်၄င်း။”')
,(2840,3,4,'(မီးခိုး၊ အငွေ့) ထွက်လွင့်သည်။ ထွက်လွင့်စေသည်။','ယက်ဂဂုဲ = မီးခိုးထွက် လွင့်သည်။ ဂဂုဲယက်၊ ဂဂုဲတိုန်ယက် = မီးခိုးထွက်စေလွင့်သည်။ || “ညံၚ်လ္ၚပၟတ်တိုပ်ဗ္ဒန် ပ္ဍဲ ပ္တေၚ်ဒေါဝ်ဖဴရ၊ သဂွံခနှိက်သ္ကာံ မဂဂုဲတိုန်ယက်ကီု။” (ဇ—၆၁။ အစွောံ။) = “မီးဖိုလယ်­ပြာ ဖုံးသော မီးကျီးကဲ့သို့ ဖွဲပြာအမှုန်ကို ရသည်ရှိသော် မီးခိုးကို ထွက်လွင့်စေသည်။” || ‘ဗဂုဲ’ လည်းရှု။')
,(2841,3,4,'(ထမင်းစားရာတွင်) ထမင်းကို လက်ဖြင့်ဖွ၍မွှေသည်။','“ဗမၞးဖျေံတဲဂဂုဲပုၚ်ဂှ် ပုၚ်လ္တူ ဂှ်ဂမ္တဴ ပုၚ်အသၟဝ်ဂှ်ၜိုဟ် ညာတ်သာ်ဝွံ ဗမၞးချပ်ရ။” (ဇ—၂၁၂။ အစွောံ။) = “ပုဏ္ဏားသည် (ထမင်းပန်းကန်­) လက်ကိုချ၍ ထမင်းကိုမွှေသောအခါ အထက်­ပူသော အောက်­အေးသော ထ မင်းကိုမြင်၍ စဉ်းစား၏။”')
,(2842,3,1,'လှပခြင်း။ တင့်တယ်ခြင်း။',NULL)
,(2842,3,3,'လှပသော။ တင့်တယ်သော။','‘ဂေါဝ်’(ကြိ) လည်း ရှု။ || “ယွံမၞးတံ၊ မူဂဂေါဝ်ချေံရော၊ မူဂဂေါဝ်ချေံဂှ်ရော” ဂးတုဲ ဟီုထိုင်သး(ချေံဂှ်)အိုတ်ရ။ (ဇ— ၁၉၁။ အစွောံ။) = “အချင်းတို့၊ လှလိုက်တဲ့မြင်းပါလား၊ လှလိုက်တဲ့မြင်းပါလား” ဟုဆိုကာ မြင်းကိုချီးမွမ်းကြကုန်၏။ || မၞိဟ်တံဂှ်ညာတ်တုဲ ဒဒှ်ရုပ်ထဝ်ဂှ် ဍေံတံဟွံသလှ်ေသက်က်ရ။ “မူဂဂေါဝ်ရုပ်ဗြဴဝွံမွဲရော။ ညံၚ်ရုပ်ဗြဴအဆေဝ်သွဝ်ရောၚ်သွံ” ဂးတဴအိုတ်ရ။ (ဇ—၅၃၁။ အစွောံ။) = လူတို့သည်မြင်ကုန်၍ ရွှေစင်ရုပ်ထုဖြစ်မှန်း လုံးဝမထင်မှတ်ကြ။ “တယ်လှလိုက်တဲ့ မိန်းကလေးပါလား။ နတ်သမီးရုပ်ရည်ကဲ့သို့ တင့်တယ်ပေစွ။” ဟုဆိုကြကုန်၏။')
,(2843,3,1,'၁။ မိုးချုန်းသံ၊ မိုးကြိုး။',NULL)
,(2843,3,1,'၂။ အၚုတ်။','ဂဂဵုဆု = သစ်ၚုတ်။ ‘ဂဂဵုကြက်လကံ’ (ဇ— ၁၅၆။ အစွောံ။) = ‘ရှားၚုတ်’ (ညောင်ကန်) || “တၞံဗပုၚ်ဂှ် ညံၚ်ဂဂဵုတူဂှ်ရ။” (ဇ—၂၄၈။ အစွောံ။) = “(ပေါက်ပင်သည်ကား) မီးလောင်ၚုတ်ကဲ့သို့ရှိ၏။” (ညောင်ကန်) ‘ဓဂဵု’ ဟုလည်း တွေ့ရသည်။')
,(2844,3,4,'မိုးထစ်ချုန်းသည်။','“(ဗောဓိသတ်ပန်ဏာ) ကံမွဲကလေၚ်စှ်ေ နူစတုမရှာတ်ဂှ် ညံၚ် ရဴဂဂဵုဂတးကီုမဒှ်။” (ဇ—၁၈၁။ အစွောံ။) = “စတုမဟာရာဇ်မှ ပြန်လည်လာသောမြှားသံသည် မိုးကြိုးသံကဲ့သို့ဖြစ်၏။”')
,(2845,3,4,'မိုးကြိုးပစ်သည်။','“(လၟဂှ်) ကာလဍေံပန်ဗောဓိသတ်ဂှ် ပ္ဍဲသ္ၚိဍေံပၠန်တုန် ဂဂဵုတး ပန်ဖျေံတုဲ သမ္ဘာဍေံလေဝ်ချိုတ် ကောန်ဍေံၜါလေဝ်ချိုတ်—။” (ဇ—၂၂၂။ အစွောံ။) = “မုဆိုးသည် ဘုရားလောင်း (မျောက်) ကို ပစ်ခတ်သောအချိန်­ မုဆိုး၏အိမ်­ မိုးကြိုးပစ်ချ၍ မုဆိုး၏မယားသည်၄င်း သားနှစ်ယောက်တို့သည်၄င်း သေကုန်၏။”')
,(2846,3,4,'မိုးချုန်းသည်။',null)
,(2847,3,1,'နှမြောခြင်း။ ချစ်မြတ်နိုးတန်ဖိုးထားခြင်း။', '‘ဂိုဟ်’ (ကြိ) လည်းရှု။')
,(2847,3,3,'နှမြောအပ်သော။ ချစ်မြတ်နိုးအပ်သော။ တန်ဖိုးထားအပ်သော။','ဒြပ်ဂဂိုဟ်ညး = နှမြောအပ်သောပစ္စည်းဥစ္စာ။ ချစ်မြတ်နိုးအပ် သောဥစ္စာ။ “ယွံရသိဒေံ၊ ယြဴပူဂဵုမွဲဂှ် ဒြပ်မွဲမဒှ်သ္ဍိုက်စိုတ်ညးဂှ် တီတဴ တုဲ ဟွံဂပ်ဂဝ်အာတ်ဟေၚ်။ ဟိုတ်နူမအာတ်ဒြပ်ဂဂိုဟ်ညးဂှ်ရ ညးဟွံဂွံသ္ဍိုက်မၠိုက်ရောၚ်။” (ဇ— ၂၅၃။ အစွောံ။) = “ငါ့ညီ (ရသေ့)၊ အကြင်ပုဂ္ဂိုလ်သည် ထိုပုဂ္ဂိုလ်၏ ချစ်အပ်သောဥစ္စာကို ချစ်အပ်၏ဟူ၍ သိရာ၏။ ထိုပုဂ္ဂိုလ်သည် ထိုဥစ္စာကို မတောင်းရာ။ အလွန်တောင်းခြင်းကြောင့် မုန်းခြင်းသည်ဖြစ်၏။” (ညောင်ကန်)')
,(2848,3,1,'ကျက်စားခြင်း။ ကျက်စားရာနေရာ။ သွားလာရာနေရာ။','“ယွံမအံက်၊ နူဂြိုပ်မ သက္ကုမၞိဟ်ဝွံဂှ် ကွာန်မဒှ်ဂ္ၚေၚ်မၞိဟ်တေံဂှ် တၞဟ်နသ္ပဒတဴဂှ် အဲသ္အာစိုပ်ရောၚ်။” (ဇ—၃၄၈။ အစွောံ။) = “ဖခင်၊ လူသူကင်းမဲ့သော ဤတောအရပ်မှ လူတို့ကျက်စားရာဖြစ်သောရွာသို့ နေထိုင်ရန်အလို့ငှာ အကျွန်ုပ်သွားရောက်ပေအံ့။” || “ယွံခ္ဍာ်၊ ဂ္ၚေၚ်ပိုဲဂၠာဲစတၞဟ်ရောၚ်။ ဂ္ၚေၚ်မၞး တံတၞဟ်ရောၚ်။ မူပမဗက်ကၠုၚ်အဲရော” ဗောဓိသတ်ဂစေံဖရာပ်ဂး။ (ဇ—၂၇၄။ အစွောံ။) = “အဆွေကျီး၊ ငါတို့ကျက်စားရာသည် တခြားဖြစ်၏။ သင်တို့ကျက်စားရာသည် တခြားဖြစ်၏။ အဘယ်ကြောင့် ငါ့ကိုလိုက်လာသနည်း” ဘုရားလောင်းခိုငှက်ဆို၏။ || “ပ္ဍဲဋ္ဌာန်ဂ္ၚေၚ်စိၚ်ဂမၠိုၚ်ဂှ် ဂစေံတၞောတ်ဗြဴမွဲ ဒက်သ္ပောဲဗဒှ်လဝ်ကောန်ရ။” (ဇ—၃၅၇။ အစွောံ။) = “တစ်ခုသောနှံစုတ် ငှက်မသည် ဆင်တို့၏သွားလာရာအရပ်­ အဥတို့ကို ထား၏။” || “ထာန်ဒမၠု မဒှ်ဂ္ၚေၚ်မၞိဟ်မ ဟွံခိုဟ်ရောၚ်။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “မိုက်မှောင်သောအရပ်မည်သည်ကား မကောင်းသောလူတို့၏ ကျက်စားရာဖြစ်၏။”')
,(2848,3,4,'လှည့်ပတ်သွားလာသည်။ ကျက်စားသည်။ ကျင်လည်သည်။','“ဗောဓိသတ်ပိုဲဒှ်မြာ် ဂေါဝ်ဂပ်လောန် ဂ္ၚေၚ်တဴပ္ဍဲဂြိုပ်ရ။” (ဇ—၃၃၉။ အစွောံ။) = “ဘုရားလောင်းသည် ဥဒေါင်းမျိုး­ဖြစ်၍ မြတ်သောတင့်တယ်ခြင်းနှင့် ပြည့်စုံသည်ဖြစ်၍ တော­ကျက်စား၏။” || “ပ္ဍဲတရဴသၟိၚ်ၜိုပ်ထဝ် မဂ္ၚေၚ်ကၠုၚ်အာတဴဂှ် ပ္ဍဲဒေါဝ်တရဴဂှ် ဆုဗပုၚ်ဇၞော် မွဲတၞံနွံ။” (ဇ—၃၇ဝ။ အစွောံ။) = “ရွှေဟၚ်္သာမင်း၏ သွားလာရာခရီး­ ပေါက်ပင်ကြီးတစ်ပင်ရှိ၏။”')
,(2849,3,4,'တောလှည့်သည်။ တောလိုက်သည်။','‘လၟဂ္ၚေၚ်ဂြိုပ်တုဲ ဂွံဖျဴနၚ်ဒြာဲမွဲရ။’ = ‘မုဆိုးသည် တောလှည့်ရာ (တောလိုက်ရာ) သမင်တစ်ကောင်ကို ရ၍ယူပြန်လာသည်။’')
,(2850,3,4,'လှည့်လည်၍ ဆွမ်းခံကြွသည်။','“ခမဳမ္ဂးဂှ် ဒးဂ္ၚေၚ်ပိဏ္ဍပါတ် လၟေၚ်ၚ်သ္ၚိ ရ။” = “ရဟန်းမည်သည် အိမ်စဉ်လှည့်၍ ဆွမ်းခံကြွရသည်။”')
,(2851,3,4,'သံသရာတွင်ကျင်လည်သည်။','“လအ်သ္ဂောံစိုပ်ဍုၚ်ဇၞော်နိဗ္ဗာန် သတ္တအ်ဒးဂ ေၚၚ်ဘဴသံသာ ရိုဟ်လၟိဟ်ဂၞန်ဟွံမာန်ရ။” =“နိဗ္ဗာန်ရွှေပြည်သို့မရောက်မှီ သတ္တဝါအပေါင်းတို့သည် ဘဝပေါင်းမရေမတွက်နိုင်အောင် သံသရာ­ကျင်လည်ကြရကုန်၏။”')
,(2852,3,4,'တစ်နေရာမှ တစ်နေရာသို့ လှည့်ပတ်သွားလာသည်။ ဒေ သစာရဳကြွချီသည်။','“ကျာ်တြဲမအာဂ္ၚေၚ်စရိတ်။” (ဇ—၁။ အစွောံ။) = “မြတ်စွာဘုရားသည် ဒေသစာရီကြွချီတော်မူသည်။”')
,(2853,3,4,'အရိုးကိုက်သည်။ အရိုးတွင်ကပ်နေသောအသားကို ကိုက်ဖဲ့စားသည်။','“ကၠဵုဂှ် ဂေငန်ဒၟံၚ်ဇုတ်ဂၠဴရ။” = “ထိုခွေးသည် အမဲရိုးကို ကိုက်နေသည်။” || “တြုံၜန်ဇုက်သၞာံဂၠဴ ကၠဵုဗြဴဂ ၚိန်စ။” (ဇ—၇၇။ အစွောံ။) = “ယောကျာ်းသည် လွန်ကိုကျစ်၏။ မြေခွေးမသည် ထိုလွန်ကို ကိုက်စား၏။”')
,(2854,3,1,'အိမ်မြှောင်။',null)
,(2855,3,1,'ဆူး။ ငြောင့်။ ချွန်ထက်သောအစ။','ဒးဂစုက် = (သစ်စ၊ ဝါးစ၊ မှန်စ၊ စသည်) စူးသည်။ “စိၚ်ဂြိုပ်မွဲ လိုန်ဒးဂစုက်ဆုဂဂဵုကြက်လကံတုဲ— ဇိုၚ်စိၚ်ဂုဟ် ဒှ်အာပတောဟ်(ပတိုဟ်)။” (ဇ—၁၅၆။ အစွောံ။) = “တောဆင်တစ်စီးသည် ရှားၚုတ်ကိုနင်းမိ၍ ခြေကိုရှားၚုတ်စူး၍ ပြည် အနာဖြစ်သွား၏။” || “ဒေဝဒတ်မဒှ်ဒၟံၚ်ဂစုက်သာသနာကျာ်။” (ဇ—၂၆။ အစွောံ။) = “ဒေဝဒတ်သည် ဘုရား၏ဆန့်ကျင်ဘက် ဆူးငြောင့်ဖြစ်၏။” (ညောင်ကန်) || “ဒေဝဒတ်မဒှ်ဂစုက်ကျာ်ဂှ် တိၚိတ်ဏာကၠေံရ။” (ဇ—၂၄ဝ။ အစွောံ။) = “ဘုရားသခင်၏ ရန်ဆူးရန်ငြောင့်ဖြစ်သော ဒေဝဒတ်ကို မြေမျို၏။” (ညောင်ကန်)')
,(2855,3,4,'ရှို့သည်။','ဂစုက်ပၟတ် = မီးရှို့သည်၊ မီးမွှေးသည်။')
,(2856,3,1,'မကောင်းသဖြင့် ဆိုအပ်သောစကား။ နားမခံသာသောစကား။','“ဟာဲခုဇ္ဇာ၊ နဂလာန်မဒှ်ဂစုက်ကတောဝ်အဲ ဗှ်ေမဟီုဂှ် အဲတိတ်ရေက်ကၠေံလတာ်ဗှ်ေရ” (ပြဘာဝတဳဂး။) (၅၅ဝ။ ဇ—၅၃၁။ ၉—၁၇ဝ။ အစွောံ။) = “ဟယ်ခုဇ္ဇာ၊ ငါ့နားမခံသာသောစကားကို နၚ်ပြောဆို ဘိသည်၊ နင့်လျှာကို ငါဖြတ်ပစ်အံ့” ဟု ပဘာဝတီဆို၏။')
,(2857,3,4,'၁။ တို့မီးရှို့မီးလုပ်သည်။','“ညံၚ်ညးတၞဟ်သ္ဂောံသေက်ဇဵုဒှ်သၞ လ္ပဂ စုက်ဂစေဝ် အကြာၜါညိ။” = “သူတစ်ပါးတို့ ခိုက်ရန်ဖြစ်ပွားရန် နှစ်ယောက်ကြားမှာ တို့မီးရှို့ မီးမလုပ်ပါနှင့်။”')
,(2857,3,4,'၂။ စကားကတ်ဖဲ့ပြောသည်။ ပြောဆိုနှောင့်ယှက်သည်။','“(တြုံ)ပိုတ်ဇိုၚ်ဂှ် ဍေံဂၠာဲဂစုက်ဂစေဝ်သၟာန်သၟုက်ခမဳတံတုဲ ခမဳသၟတ်တံဂှ်ကီု သာမဏဳတံဂှ်ကီု သှ်သၟာန်ဍေံဟွံဒးတုဲ ဍေံဂရိုဟ်ပျုတ်ဗ္ဒေက် တ္ၜေဟ်လက်ခမဳတံရ။” (ဇ—၂၂၇။ အစွောံ။) = “ထိုၚတုံးသည် ရဟန်းတို့အား စကားကတ်ဖဲ့နှောင့်ယှက်သော မေးခွန်းများကိုမေး၍ ရဟန်းငယ်တို့သည်၄င်း သာမဏေ တို့သည်၄င်း သူ့မေးခွန်းများကို မဖြေဆိုနိုင်ပါက ရဟန်းတို့ကို ကဲ့ရဲ့အရှက်ခွဲဆဲဆို၏။”')
,(2857,3,4,'၃။ ဆဲဆိုသည်။ ဆဲရေးသည်။','“မၞိဟ်လက်ဖာဂစုက်ဂစဳညးဂှ် ဍေံက္ဍုဟ်ဟွံထိုင်သး။” (ဇ—၄၇၃။ အစွောံ။) = “သူတစ်ပါးအား ဆဲရေးသောလူကို သူမုန်း၍မချီးမွမ်း။”')
,(2858,3,4,'တို့မီးရှို့မီးလုပ်သည်။ တိုင်ကြားသည်။','“တ္ၚဲဏအ်အဲဒြေပ်ဘာ ဗှ်ေလ္ပဂစုက်စကဵုအ္စာ ဘာညိ။” = “ဒီနေ့ငါကျောင်းပြေးတာကို ကျောင်းဆရာအား နင်သွားမတိုင်ကြားပါနှင့်။”')
,(2859,3,4,'စစ်ဆေးသည်။ မေးမြန်းစုံစမ်းသည်။ စပ်စုသည်။ (ပါဠိ—သြစရတိ)','“ဍေံဏအ်မွဲ ဂစော်ဂစဳကွေံ၊ ဗက်ဂၠာဲသၟာန်ဒၟံၚ် ပရေၚ်ညးတၞဟ်။” = “ဤသူသည် တကယ်စပ်စုသည်၊ သူများ အရေး လိုက်မေးနေသည်။”')
,(2860,3,4,'ငုံ့သည်။','ဂစိုၚ်က္ဍိုပ် = ခေါင်းငုံ့သည်။ “သၟတ်ဗၠာဲဂမၠိုၚ် ဟီုဗၟက်ဝေၚ်တုဲ သၟတ် ဗြဴဝုတ်ဂှ်ဂွတုဲ ဂစိုၚ်လဝ်က္ဍိုပ်ရ။” = “လူပျိုများကျီစယ်ပြောဆိုသဖြင့် ထိုမိန်းမပျိုသည် ရှက်၍ ခေါင်းငုံ့ထားသည်။”')
,(2861,3,4,'ပြွတ်တံနှင့်ပန်းထွက်အောင်လုပ်သည်။ ပန်းထွက်သည်။','“တၟအ်လးဂှ် ပါ်ဒကးအာတုဲ ဍာ်ဂစတ်တိုန် တၟာတၞံတာရ။” = “ကျောက်ဖျာကွဲပေါက်သွားပြီး ထန်းလုံးကြီးလောက်ရှိသော ရေပန်းထွက်လာသည်။”')
,(2862,3,4,'သတ်သည်။',NULL)
,(2862,3,4,'သတ်သည်။','ပကာဂစိုတ် = သေဆုံးသည်။')
,(2862,3,1,'၁။ သေခြင်း။','သၟိၚ်ဂစိုတ် = သေမင်း။ ဘဲဂစိုတ် = သေဘေး။ || “ပ္ဍဲကာလမညောန်ကဵုဂစိုတ်ဂှ်ရ သၟိၚ်သုဒဿနစက္ကဝဝ်ဂှ် စှ်ေကၠုၚ်နူပြာသာဒ်လတူတေံရ။” (ဇ—၉၅။ အစွောံ။) = “သေခြင်းနှင့်နီးသောကာလ­ သုဒဿ နစကြာမင်းသည် အထက်ပြာသာဒ်မှ ဆင်းလာ၏။” || “ဝေၚ်ကၠေံနူနိဗ္ဗာန်မွဲတုဲ ညးမဗၠးအာနူဂ စိုတ်မ္ဂး ဟွံမွဲရ။” (ဇ—၁၅၉။ အစွောံ။) = “နိဗ္ဗာန်မှတစ်ပါး သေခြင်းမှလွတ်သောသူမည်သည် မရှိ။”')
,(2862,3,1,'၂။ အသတ်။','ဂစိုတ်လိက်မန်စှ်သာ် = မွန်စာရေးထုံး အသတ်ဆယ်မျိုး။')
,(2863,3,4,'(ဟင်းချက်ရာတွင်) ဆီသတ်သည်။',null)
,(2864,3,4,'သတ်ဖြတ်သည်။',null)
,(2865,3,4,'အသက်ကိုသတ်သည်။','“ပွမဂစိုတ်လမျီုညးဂှ် ဒှ်ဒုဟ်ပါဏာတိပါတ် ဒှ်ပွသရာံ ပါပ်ရ။” = “သူ့အသက်ကို သတ်ခြင်းမည်သည် ပါဏာတိပါတ်အပြစ်ဖြစ်၍ မကောင်းမှုအကုသိုလ်ဖြစ်သည်။”')
,(2866,3,4,'၁။ ကြိုးစားအားထုတ်သည်။ ရုန်းကန်သည်။','‘ဂစာန်ကလောန်’ = ‘အလုပ်ကြိုး စားသည်။’ || ‘ဂစာန်လိက်’ = ‘စာကြိုးစားသည်။’')
,(2866,3,4,'၂။ တွန်းသည်။ တွန်းကန်သည်။','ဂစာန်လဝ် = ထောက်နှင့်တွန်းကန်ထားသည်။ || “ပ္ဍဲမကၠောံကြုၚ်ဂှ် ကောန်သေဋ္ဌဳဂှ် ဟွံမြက်ကဵုဍာ်ဇ မောဝ်ဂှ်တုဲ ဇမောဝ်ဍာ်ဂစာန်ပ္တိတ်ဏာ ဇရေၚ်ၜဳဇၞော်ရ။” (၅၅ဝ။ ဇ—၄၈၂။ ၇—၂၁၂။ အစွောံ။) = “ချောင်းကိုကူးရာ­ သူဌေးသားသည် ရေအယဉ်­မမြန်သဖြင့် ချောင်းရေအယဉ်က ပင်လယ် သမုဒ္ဒရာဆီသို့ တွန်းထုတ်လိုက်၍ မျောပါသွား၏။”')
,(2867,3,4,'အသက်လွတ်အောင် ရုန်းကန်လှုပ်ရှားသည်။ အသက်ငင်သည်။',null)
,(2868,3,1,'တောင်ဝှေး။',null)
,(2869,3,1,'ချဉ်ပေါင်ပင်။',null)
,(2870,3,1,'ငှက်။',null)
,(2871,3,1,'ငှက်အမျိုးမျိုးကို ခြုံ၍ခေါ်ဆိုသောအမည်။ ကျေးငှက်သာရကာ။',null)
,(2872,3,1,'ကောက်စိုက်စူး။',null)
,(2873,3,1,'ထမင်းစားရန်ခက်ရင်း။ (ဇွန်းခက်ရင်း)',null)
,(2874,3,4,'ကြဲသည်။ ဖြန့်ကြဲသည်။ ပြန့်ကြဲအောင်လုပ်သည်။','“ခဍာ်ပဝ်အာ ကဏေအ်ဂၠဴၜံက်စ္ဍး ဂစာဲကၠေံတုဲ (ဂၠာဲစစၟရ။)” (ဇ—၄၂။ အစွောံ။) = “ကျီးသည်ပျံသွားကာ နွားချေးကို နှုတ်သီး ဖြင့်ပေါက်၍ ဖြန့်ကြဲပြီးလျှင် ပိုးမွှားများကို ရှာစားသည်။” || “ဇနပဒကလျာဏဳ ဗၠိုပ်ဟုံကြဴသော် ဂှ် သီုသော်မဟွံဂွံသ္ကဟ် ပသဟ်ဂစာဲတလာဲလဝ်ဂှ် ကွာ်တိတ်ပ္ဍဲတမေၚ်။” (ဇ—၁၈၂။ အစွောံ။) = “ဇနပဒကလျာဏဳသည် ရေချိုးခေါင်းလျှော်ပြီး မခြောက်သေးသောဆံပင်ကို ဖားလျားချဖြေ ဖြန့်လျက် အိမ်ကပြင်သို့ လျှောက်ထွက်လာ၏။” || “ယွံမၞးတံ၊ မၞးတံဂစိုတ်ကၠေံဂၞကျာ်တုဲ ကုတ် ဒန်ဂစာဲကၠေံတုဲ ထောံဖျေံကတိုၚ်သ္ၚိဍာ်ဂှ်ရ” သၟိၚ်ဂး။ (ဇ—၅၂၈။ အစွောံ။) = “အချင်းတို့၊ သၚ် တို့သည် မိဖုယားကို သတ်ပစ်ပြီးလျှင် မိဖုယားကိုယ်ကို ခုတ်ဖြတ်ကြဲပစ်၍ အိမ်သာတွင်း­ ပစ်ချကုန်လော့” ဟုမင်းဆို၏။')
,(2875,3,4,'ကြဲသည်။ ဖြူးသည်။ ဖြန့်ကြဲသည်။ ပြန့်ကြဲစေသည်။ ဖရိုဖရဲကြဲသည်။ (ပါဠိ— အာကိရတိ/သြကိဏ္ဏ)','‘ဂစာဲ’ နှင့်အတူတူ။ || “နဗတဳသာ်သြန်တံဂှ် ကဵုဒြာတ်ဂစာဲဖဍာဲလဝ်ရ။” (ဇ—၄၉၇။ အစွောံ။) = “ငွေရောၚ်သဲတို့ဖြင့် ပက်ကြဲထားစေ၏။”')
,(2876,3,1,'ဝန်ကိုရွက်ရာတွင် ခေါင်းပေါ်တွင် တၚ်ခုရသောအဝတ်ခွေ။ ခေါင်းခု။ (ပါဠိ—အဏ္ဍူပက)',null)
,(2877,3,1,'ထွေးပြီးသောတံတွေး။ တံတွေးပေါက်။','‘ကသှ်/ဍာ်ကသှ်’ နှင့်အတူတူ။ || “ဗြဴ မှောင်မှစှ်တြဴလ္ၚီဂှ်ကီု တိုက်ဒြပ်တံဂှ်ကီု ကောန်တြုံကောန်ဗြဴတံဂှ်ကီု ထောံကၠေံညံၚ်ဍာ်ဂစှ်တုဲ တိတ် ဂြိုပ်ဟေမဝန်တုဲ ပကၠေံခမဳရ။” (ဇ—၄ဝ၆။ အစွောံ။) = “တစ်သောင်းခြောၚ်ထောၚ်ကုန်သော မောင်းမတို့ကို၄င်း၊ ဥစ္စာတိုက်တို့ကို၄င်း၊ သားတော်သမီးတော်တို့ကို၄င်း၊ ထွေးအပ်သောတံတွေး ပေါက်ကဲ့သို့ စွန့်ပစ်၍ ဟိမဝန္တာတောသို့ထွက်၍ ရဟန်းပြု၏။”')
,(2878,3,1,'အကြေး။','ဂစေဟ်က = ငါးအကြေး။')
,(2878,3,4,'အကြေးခွံခွါသည်။','“ကတုၚ် လဝ်ဍာ်ဂှ် ဂစေဟ်ထောံညိ။” = “ရေစိမ်ထားသောငါးကို အကြေးခွံခွါလိုက်ပါ။”')
,(2879,3,1,'ရေရွတ်သည်။ မြည်တမ်းသည်။','“ဝေၚ်အာနူတဳလမၞုံပိုန်တုဲ စ္ၜုဲစ္ၜော်အဲသ္အာၚ်ဟွံမွဲရ။” စိၚ်ဗြဴဂှ်ပ္တီကျာ်တြဲတုဲ သီုမဂစေံဂစောတ် ယာံတဴရ။(ဇ—၄ဝ၉။ အစွောံ) = “ဘုန်းတော်ကြီးသော အရှင်ဘုရားမှတစ်ပါး အကျွန်ုပ်­ ကိုးကွယ်ရာသည်မရှိ” ဟု ထိုဆင်မသည် မြတ်စွာဘုရားကိုသိစေ၍ ရေရွတ်မြည်တမ်းလျက် ငိုကြွေး၏။ || “(ဗောဓိသတ်သၟိၚ်စိၚ် ဆဒ္ဒန် ဒးပွန်ကံလၟတုဲ ဂၞကျာ်မဟာသုဘဒ္ဒါဂှ်) သီုကဵုသဓဵုသမ္ၚဟ် ရေရောတ်ဂစေအ်ဂစောတ် ဇွိတ် သပေါတ်တၠသ္ၚိဇကုတုဲ သီုကဵုဍာ်ရမတ် မပေၚ်တဴနကဵုဂဍောၚ်မတ်ၜါဂှ်ရ။” (ဇ—၅၁၄။ အစွောံ။) = “ဘုရားလောင်းဆဒ္ဒန်ဆင်မင်းသည် မုဆိုး၏မြှားချက်ကို ထိမှန်၍ မဟာသုဘဒ္ဒါဆင်မိဖုယားသည် ပူဆွေးသောကဖြင့် ငိုကြွေးမြည်တမ်းလျက် မိမိခင်ပွန်း အားပွတ်သပ်၍ မျက်လုံးနှစ်ဖက်တို့­ မျက်ရည်တို့ဖြင့်ပြည့်၏။” || “ကၠဵုဂှ်ကၠုၚ်စိုပ်စိၚ်ဂှ်တုဲ နလပှ်မိန်ကေတ်ကၠဵုဂှ်တုဲ ပ္တိုန်ဏာလတူကၟံၚ် တုဲ ဂစေဝ်ဂစောအ် ရေဝ်ရောတ်ယာံတဴရ။” (ဇ—၂၇။ အစွောံ။) = “ခွေးရောက်လာသည်ရှိ သော် ဆင်သည် နှာမောင်းဖြင့် ခွေးကိုပွေ့ချီ၍ ဦးကင်းပေါ်­တင်၍ မြည်တမ်းလျက်ငို၏။”')
,(2880,3,1,'ဇကာ။ ဆန်ခါ။',null)
,(2881,3,4,'တုံ့ဆွဲသည်။',null)
,(2882,3,1,'သပေါ့ပင်။','ဒကဝ်ဂဇာၚ် = သပေါ့ဖျာ။')
,(2883,3,4,'ဆောင့်ကြောင့်ထိုင်သည်။',null)
,(2884,3,4,'အတုံးကလေးဖြစ်အောင်တုံးသည်။ နုပ်နုပ်စင်းသည်။','ဂဇီဖျုန် = အသားကို နုပ်နုပ်စဉ်းသည်။')
,(2885,3,4,'ကောက်ညှင်း၊ ထန်းလျက်စသည်ကို တဆေးနှင့်ဖောက်သောသေရည်။ ကစော်။',null)
,(2886,3,4,'ရှူးတိုက်သည်။','ဂဇုဟ်ကဵုကၠဵု = ခွေးနှင့်ရှူးတိုက်ပေးသည်။')
,(2888,3,5,'ရိုသေစွာ။ ဂရုတစိုက်။ စိတ်အားထက်သန်စွာ။ အားတက်တရော။','“(ကုဣသိဂှ်) ညးကွာန်တံဂှ် ဥပ္ပကာနကဵု ဂဇှ်ေဟေၚ်။” (ဇ—၁၃၈။ အစွောံ။) = “ရွာ­နေသောလူတို့သည် ရသေ့ကို ရိုသေစွာလုပ်ကျွေး ကုန်၏။” (ညောင်ကန်) “သၟတ်ဗြဴဂှ် ဍေံကၠောန်ၜိုတ်ကေုာံခါံသဳဗြဴဍေံဂှ် နဂဇေဟ်ရ။” (ဇ— ၄၁၇။ အစွောံ) = “ထိုသူငယ်မသည် လင်၏အမိကို ရိုသေစွာလုပ်ကျွေး၏။” || “ဗမၞးမတၠဂုန် အဲဝွံ နဂဇှ်ေ သီုလမောၚ်ဒဒိုက်ဟေၚ် မကၠောန်ၜိုတ်မြိမြန်ဇၞော်ပၟဝ်လဝ်အဲ—” ဂၠဴဂှ်ချပ်။ (ဇ—၂၈။ အစွောံ။) = “ငါ၏ဖခင်ပုဏ္ဏားသည် ငါ့ကို ဂရုတစိုက် ငြိုငြင်သဖြင့် လုပ်ကျွေးပြုစုမွေးမြူထား ၏။”')
,(2889,3,4,'ထိုင်သည်။',null)
,(2890,3,4,'(အလုပ်လုပ်စရာမလိုဘဲ) အသက်မွေးရသည်။ ထိုင်စားသည်။','“နိဿဲကဵုသေဋ္ဌဳတၠ ဒါန်တုဲ တွဵုလမျီုဟွံဒးကၠောန်ၜိုတ် သ္ဂောံဂဇအ်စရ။” (ဇ—၇၈။ အစွောံ။) = “အလှူ့ရှင်သူဌေး ကိုမှီ၍ တစ်သက်ပတ်လုံး လုပ်ကိုင်စရာမလိုပဲ ထိုင်စားရတော့မည်။”')
,(2891,3,4,'တင်ပလင်ခွေထိုင်သည်။',null)
,(2892,3,4,'တရားကျင့်သည်။ တရားထိုင်သည်။ ကမ္မဋ္ဌာန်းထိုင်သည်။',null)
,(2893,3,4,'ထီးနန်းစိုးစံသည်၊ နန်းထိုင်သည်၊ မင်းပြုသည်။',null)
,(2894,3,4,'(ဆရာတော်) ကျောင်းထိုင်သည်။',null)
,(2895,3,4,'ရုံးထိုင်သည်။ အကြီးအကဲဖြစ်သည်။',null)
,(2896,3,4,'သပ်ယပ်စွာထိုင်သည်။ (?)',null)
,(2897,3,4,'(လုံချည်၊ ထဘီ၊ သင်းပိုင်စသည်) ခပ်နိမ့်နိမ့်ဝတ်သည်။','ဂဇေအ်လဝ်ဂၠိက် = လုံချည်ကို (ခြေမျက်စိဖုံးသည့်တိုင်) ခပ်နိမ့်နိမ့်ဝတ်ထားသည်။ (ဒယဉ့်ဆွဲသည်)')
,(2898,3,1,'တန်ဆာ။ အဆင်တန်ဆာ။','ဂ္ညိကတောဝ် = နားတန်ဆာ။ ဂ္ညိက္ဍိုပ် = ဦးခေါင်းတန်ဆာ။ ဂ္ညိကအ် = လည်အဆင်တန်ဆာ။ ဂ္ညိတဲ = လက်ဝတ်တန်ဆာ။ “ပ္ကဴထဝ်မဒှ်ဂ္ညိက္ဍိုပ်ရောၚ်။” (ဇ—၂၉၇။ အစွောံ။)= “ရွှေပန်းသည် ဦးခေါင်းတန်ဆာဖြစ်၏။” || “ဒးကာလညးကဵုမ္ၚဵုစိၚ်တုဲ ဗၞတ်စိၚ်ကၠံဟေၚ် တိတ်ရေၚ်ပ္တန်လဝ်တုဲ ဂ္ညိလပှ်စိၚ်ကီု ဂ္ညိကၟံၚ်စိၚ်ကီု ဂ္ညိဒြၚ်စိၚ်ကီု ဂ္ညိက္ဍိုပ်စိၚ်ကီု — ပ္ဍဲမုက်ရၚ်သၟိၚ်ဂှ် ညးကၠုၚ်ဂ္ညိလဝ်ရ။” (ဇ—၁၆၃။ အစွောံ။) = “ဆင်မၚ်္ဂလာပွဲဆင်နွှဲရန် အချိန် ရောက်၍ တစ်ရာသောဆင်တို့ကို ထုတ်ဆောင်၍ စီတန်းစေပြီးလျှင် ဆင်နှာမောင်းတန်ဆာကို ၄င်း၊ ဆင်ဦးကင်းတန်ဆာကို၄င်း၊ ဆင်စွယ်တန်ဆာကို၄င်း၊ ဆင်ဦးခေါင်းတန်ဆာကို၄င်း မင်းရင်ပြင်­ တန်ဆာဆင်ထားစေ၏။”')
,(2898,3,4,'တန်ဆာဆင်သည်။ ဆင်ယင်သည်။','‘ဂ္ညိဂ္ညာတ်’ (န/ကြိ)နှင့်အတူတူ။ || “အိုတ်အလုံဍုၚ်ဂှ် ညံၚ်ရဴဍုၚ်ဒေဝတဴကီု ဂ္ညိလဝ်တုဲ—။” (ဇ—၁၄၇။ အစွောံ။) = “မြို့ကို နတ်မြို့ကိုကဲ့သို့ တန်ဆာဆင်ကုန်၏။” (ညောင်ကန်)')
,(2899,3,1,'အဆင်တန်ဆာ။ ဆင်ယင်စရာ။','“ဂ္ညိဂ္ညာတ်မပ္တံကဵုယာတ်ဂှ် ပ္ဍဲသ္ၚိကလောမၞးတံဂှ် မၞးတံ ကၠတ်ကေတ် လ္ပကဵုညးတီညာတ်သက်က်ညိ။ ဂွံတုဲ ကေတ်နၚ်ကဵုအဲညိ” အ္စာဂး။ (ဇ—၃ဝ၅။ အစွောံ။) = “အဝတ်အစရှိသော အဆင်တန်ဆာတို့ကို သင်တို့ဆွေမျိုးများအိမ်မှ လူသူမသိအောင် ခိုးယူ၍ ငါ့ဆီယူလာခဲ့ကြကုန်လော့။” || “ဒေဝတဴဗြဴသိရဳဂှ် နဂ္ညိဂ္ညာတ်သာ်ထဝ်သက်က်ဂှ် ဂ္ညိဂ္ညာတ်တုဲ ပြာပ်ကၠုၚ်ရ။” (ဇ—၃၈၂။ အစွောံ။) = “သိရီနတ်သမီးသည် ရွှေအဆင်းရှိသောအဆင်တန် ဆာသက်သက်ကို တန်ဆာဆင်၍ လာ၏။”')
,(2899,3,4,'၁။ တန်ဆာဆင်သည်။ ဆင်ယင်သည်။','“သဘၚ်ဇၞော်ဒှ် အလုံဍုၚ်တမ္ညဝ်ဒၟံၚ် ညးဂ္ညိဂ္ညာတ်လဝ်ဍုၚ် ညံၚ်ရဴဍုၚ်သွဝ်ကီု။” (ဇ—၁၂၂။ အစွောံ။) = “ပွဲသဘၚ်ကြီးကို ဆင်နွှဲကြရာ မြို့အလုံးသည် အုန်းအုန်းကျွက်ကျွက် စည်ကားလျက်ရှိပြီး မြို့ကို နတ်မြို့ကဲ့သို့ တန်ဆာဆင်ထား၏။”')
,(2899,3,4,'၂။ (သစ်ပင်စသည်) အရွက်အခက်အခွနှင့် ပြည့် စုံသည်။ ဝေဆာသည်။ စည်ပင်ပြန့်ပွားသည်။','“ပ္ဍဲသ္ကဲတရၚ်ဍုၚ်ဂှ် တၞံဇြဲမွဲတၞံ မဂ္ညိဂ္ညာတ်တဴဂှ် သၠးဒၟံၚ်ဂှ် ဗောဓိသတ်ပ္တီသၟိၚ်တုဲ ကဵုကလော်ဒၟံၚ် ပ္ဍဲတၞံဇြဲဂှ်ရ။” (ဇ—၃၉၈။ အစွောံ။) = “မြို့တံခါးနံ ဘေး­ အခက်အခွနှင့်ပြည့်စုံသော ဝေဆာသောညောင်ပင်တစ်ပင် လပ်နေသည်ကို ဘုရားလောင်းသည် မင်းအားအသိပေး၍ ဘီလူးကို ထိုညောင်ပင်­ နေစေ၏။” || “ပ္ဍဲဥဒျာန်ဂှ် ဆုမယေအ်မွဲတၞံ သတပ်သၠုၚ်ဂ္ညိဂ္ညာတ်တဴဂှ်နွံ။” (ဇ—၁၂၁။ အစွောံ။) = “ထိုဥယျာဉ်­လျှင် — ဖြောင့်သောပင်စည် ရှိသော ဝန်းသောအခက်အခွနှင့်ပြည့်စုံသော — မၚ်္ဂလာသစ်ပင်သည်ရှိ၏။” (ညောင်ကန်)')
,(2900,3,1,'ခိုက်ရန်။ ခိုက်ရန်ပြုခြင်း။ ငြင်းခုံခြင်း။ (ပါဠိ—ဘဏ္ဍန/ကလဟ)',NULL)
,(2900,3,4,'ခိုက်ရန်ဖြစ်သည်။ အငြင်းအခုံပြုသည်။','“သတ္တအ်ဂမၠိုၚ်ဂှ် ဟိုတ်နူနွံကဵုစိုတ်တုဲ ဒးဆာန် ကၟိန် ထေဲပၞတ်ဂ္ညိဂ္ညန် ဒှ်ဒဒိုက်တၞဟ်ဟ်သာ်ရ။” (သၚ်္ခါရဘေဒနဳ/ဝိန္ဒသာရ) = “သတ္တဝါအပေါင်း တို့သည် စိတ်ရှိကုန်သောကြောင့် ချစ်ခင်ရ၏၊ စိတ်ဆိုးခိုက်ရန်ဖြစ်ရကုန်၍ ဒုက္ခအမျိုးမျိုး ဖြစ် ကြရသည်။” || “ယွံကျာ်တဳလပိုန်၊ — ပိုဲဍိက်ညးဂမၠိုၚ်ဂှ် နမဂညေံဂညန်မသွိုက်ဇွဵုဂှ် ကြက်ပပြာ ကတ်ရအဴ” ခမဳမွဲဂးကဵုကျာ်တြဲရ။ (ဇ—၄၂၈။ အစွောံ။) = “ဘုန်းတော်ကြီးတော်မူသောအရှင် ဘုရား၊ အကျွန်ုပ်တို့သည် ခိုက်ရန်အငြင်းအခုံဖြင့် ထင်ရှားပါကုန်လတ္တံ့။”')
,(2901,3,4,'တန်ဆာဆင်ယင်သည်။ လှပတင့်တယ်သည်။',null)
,(2902,3,4,'(ခေါင်း) ညိတ်သည်။',null)
,(2903,3,4,'ခေါင်းညိတ်သည်။ သဘောတူကြောင်းပြသည်။',null)
,(2904,3,4,'ညှိတ်သည်။','ဂညော်ကအ် = ခေါင်းညှိတ်သည်။')
,(2905,3,3,'‘ခ္ဍဴ’ ရှု။',null)
,(2906,3,4,'အရှက်ရစေသည်။ အရှက်ခွဲသည်။','“ကွတ်စၞာဲမဂဍိုက်ကဵုဇကု ဖျောံကလောဂမၠိုၚ်ဂှ် လ္ပကွာ်ဗက်ညိ။” (ဇ—၉၈။ အစွောံ။) = “မိမိကိုယ်ကို အရှက်ရစေသော ဆွေမျိုးတို့၏ဂုဏ်သ ရေကို ဖျက်ဆီးသော စဉ်းလဲသောအတတ်နောက်သို့ လိုက်မလျှောက်ပါလေနှင့်။”')
,(2907,3,4,'အရှက်ခွဲသည်။','“ဒးဂၞပ်ကဵုအဲရောၚ်ဂးတုဲ အဲကၠုၚ်ရောၚ်၊ လၟုဟ်ဂဍိုက်ဂဝအဲ ရောၚ်။” (ဇ—၂၆၆။ အစွောံ။) = “ငါ့ကို ကြိုက်သည်ဆို၍ ငါလာခဲ့သည်။ ယခုငါ့အား အရှက်ခွဲပြန်၏။” || “(ကောန်သမၠီုမယုတ်မာဝွံ) ပဂဍိုက်ဂဝအဲရောၚ်သွံ။” (ဇ—၉၈။ အစွောံ။) = “မိုက်မဲယုတ်မာသောသားသည် ငါ့အား အရှက်ခွဲသည်တကား။” || ‘ထဍိုက်ဂဝ’ ဟုလည်း ရေးထုံးရှိသည်။')
,(2908,3,1,'ခရမ်းသီး။','‘ခ္ဍောၚ်’ ဟုလည်းရေးသည်။')
,(2909,3,1,'လည်ချောင်း။','‘ခ္ဍောၚ်ကအ်’ ဟုလည်းရေးသည်။')
,(2910,3,1,'၁။ မျက်လုံး။',NULL)
,(2910,3,1,'၂။ မျက်ရှု။','ကောန်ဖျုန်ဂြိုဟ်ဂဍောၚ်မတ် = ရင်နှစ်သည်းချာ။ သည်းချာမျက်ရှု။ || ‘ခ္ဍောၚ်မတ်’ ဟုလည်းရေးသည်။')
,(2911,3,4,'(န) ‘ခ္ဍတ်တဲ’ ရှု။',null)
,(2912,3,4,'(န) ‘ခ္ဍန်’ ရှု။',null)
,(2913,3,4,'၁။ လျော့လျည်းသည်၊ မြဲမြံခြင်းမရှိ။','“ပ္ဍဲဓဝ်သုစရိုတ်ပိစွံ မတွံဂး ကာယသုစရိုတ် ဝစဳသုစရိုတ် မနောသုစရိုတ်တအ်ဂှ် သြဟ်ပ္တဴလဝ်လၟိုန် စိုတ်လ္ပကဵုဂဍောပ်ညိ။” = “ကာယသုစရိုက် ဝစီသုစရိုက်နှင့် မနောသုစရိုက်တည်းဟူသော သုစရိုက်တရားသုံးပါးကို အ မြဲဆောက်တည်လျက် စိတ်ကိုမလျော့လျည်းပါစေနှင့်။”')
,(2913,3,4,'၂။ တွန့်လိပ်သည်။ ကျုံ့သည်။','“ကာလလအ်အာ ဒွံကျာဂမ္တဴတုဲ ဒးဓါတ်ဂမ္တဴတ္ၚဲ ဇွစိၚ်သကှ်ဂဍောပ်အာ(ရ။)” (၅၅ဝ။ ဇ—၁၄၈။ ပ— ၄၁၄။ အစွောံ။) = “ကာလရှည်ကြာလတ်သော် နွေအခါ နေကလည်းပူ လေကလည်းတိုက်သဖြင့် ဆင်သေကောင်သည် တဖြည်းဖြည်း ခြောက်ကပ်တွန့်လိပ်လာ(၏။)” (ခေတ်မီ—၅၅ဝ။ ပ— ၅၈၈။ အရှင်ဓမ္မဿာမီဘိဝံသ။)')
,(2913,3,4,'၃။ (ထီးစသည်) ပိတ်သည်။ (တိရစ္ဆာန်အမြီး၊ နားရွက်စသည်) ကုပ်သည်။','“ဗြဲဍးအာတုဲရ၊ ဂဍောပ်ထောံက္ဍိုၚ်ဂွံရ။” = “မိုးစဲသွားပြီ၊ ထီးကို ပိတ်လိုက်လို့ရပြီ။” || “ကၠဗြန်မွဲဂှ် ဍေံဂဍောပ်ကဝေန်လဝ်ဗတ။” (၅၅ဝ။ ဇ—၅၂၈။ ၉—၆၁။ အစွောံ။) = “တစ်ခုသောကျားသစ်သည် အမြီးကို ကုပ်ကွေးထားသည်။” || “(စိၚ်)နာဠာဂိရိဂှ် —— ဂဍောပ် သၠကတောဝ် ဖျဝ်လပှ်တုဲ ကွာ်ကၠုၚ်ဖျေံက္ဍိုပ် တံဇိုၚ်ကျာ်တြဲရ။” (၅၅ဝ။ ဇ—၅၃၃။ ၉—၂၁၇။ အစွောံ။) = “နာဠာဂိရိဆင်သည် နားရွက်ကိုကုပ်၍ နှာမောင်းကိုနှိမ့်ချလျက် လျှောက်လာပြီးလျှင် မြတ်စွာဘုရားခြေတော်ရင်း­ ဝပ်စင်းလေ၏။”')
,(2914,3,4,'‘ခ္ဍောပ်ကဝေန်’ ရှု။',null)
,(2915,3,4,'လုံ့လလျှော့သည်။ ကြိုးစားအားထုတ်မှုကို ရပ်စဲပစ်သည်။',null)
,(2916,3,4,'ကော်သည်။ ထိုးကော်သည်။ (တစ်စုံတစ်ရာဖြင့် ထိုးယူမြှောက်တင်သည်။)','“ပူဂဵုမဂ စိုတ်မဂှ် —— နေၚက်ဂရးပသဲဍာဲဍာဲဂှ် ပၟၚ်နရက်တံ ဂဍာဲပါၚ်တုဲ ဍေံတံၚ်ပ္တိတ်လတာ်တုဲ ဍေံစင် စုတ်ထဏောန်တုဲ ဍေံဓဇက်ဏာရ။” (၅၅ဝ။ ဇ—၅၃ဝ။ ၉—၁၁၇။ အစွောံ။) = “အဘကိုသတ် သောသူအား ငရဲထိန်းတို့သည် ရဲရဲတောက်လောင်နေသော သံထွန်သွားတို့ဖြင့် ပါးစပ်ကိုထိုးကော်၍ လျှာကိုဆွဲထုတ်ပြီးလျှင် မျှားချိတ်ဖြင့်ချိတ်၍ တရွတ်တိုက်ဆွဲယူသွား၏။”')
,(2917,3,1,'နားဖာကလော်။ နားဖာချူ။ (ပါဠိ—ကဏ္ဏမလဟရဏဳ)','‘ခ္ဍဟ်’ (ကြိ) လည်းရှု။')
,(2918,3,1,'မုန်းတီးခြင်း။ အမုန်း။','“လ္ပကဵုဒှ်ဂဍုဟ်ညးဂမၠိုၚ်ညိ။” = “လူအများ၏မုန်းတီးခြင်းကို မဖြစ်ပါစေနှင့်။” ‘က္ဍုဟ်’ ရှု။')
,(2919,3,3,'၁။ ရှေ့ဘက်­ရှိသော။ မျက်နှာမူရာဘက်­ရှိသော။ ရှေ့မှောက်ဖြစ်သော။','“ညးနွံဂတ အဲရ။” = “ငါ့ရှေ့မှာ သူရှိသည်။” || “ဂတမိမၜါ။” = “မိဘနှစ်ပါးရှေ့မှောက်­။”')
,(2919,3,3,'၂။ ရှေ့လာမည့်။ အနာဂတ်ကာလဖြစ်သော။','“ထပှ်တ္ၚဲဂတ ကွာန်ပိုဲဝေၚ်သဘၚ်ကျာ်ရောၚ်။” = “ရှေ့ လာမည့်ခုနစ်ရက်တွင် ငါတို့ရွာမှာ ဘုရားပွဲတော်ကစားကြမည်။”')
,(2919,3,5,'ရှေ့မှ။ ရှေ့မှာ။','“ကကၟက်အာကြဴ ကဗြဴအာဂတ။” (ဇ—၂၁၆။ အစွောံ။) = “ငါးဖိုသည် နောက်မှသွား၍ ငါးမသည် ရှေ့မှသွား၏။”')
,(2919,3,4,'မျက်နှာမူသည်။ ရှေးရှုသည်။','“ဒၞာဲဒၞာဲမဂတအာ သတြုဒြိုဟ် လ္ပကဵုမာန်ညိ။” = “ရှေးရှုသွားလေရာ ရန်သူမနှိပ်စက်နိုင်ပါစေသတည်း။”')
,(2920,3,1,'ရှေ့မှောက်။ အရှေ့။','“ပ္ဍဲဂတမုက်အဲ လ္ပသေက်ဇဵုညးသ္ကအ်ညိ။” = “ငါ့ရှေ့မှောက် မှာ ရန်မဖြစ်ကြပါနှင့်။” || “ဗောဓိသတ်ကလေၚ်ကၠုၚ်စိုပ် ဂတမုက်သ္ၚိရ။” (ဇ—၁၉၉။ အစွောံ။) = “ဘုရားလောင်းသည် ပြန်လာ၍ အိမ်ရှေ့သို့ရောက်၏။”')
,(2920,3,4,'မျက်နှာမူသည်။ ရှေ့ရှုသည်။','“မူပဂတဒၟံၚ်မုက်ကဵုတ္ၚဲဂှ်ရော” ကၞိဂမၠိုၚ်သၟာန်တဴကၠဵု။ (ဇ—၁၂၈။ အစွောံ။) = “အ ဘယ်ကြောင့် နေနှင့်မျက်နှာမူနေပါသနည်း။”')
,(2921,3,5,'မျက်မှောက်အားဖြင့်။ မျက်မြင်ဒိဋ္ဌအားဖြင့်။ လက်တွေ့အားဖြင့်။','“ယြဴပူဂဵုမွဲ ဂွံ သိပ်ဂၠိပ်ဟုဲဏှဴ ဂကောံတၠပညာတုဲ ကလိဂွံတသိုက်ဂတမတ်ကီုရ။” (ဇ—၁၉ဝ။ အစွောံ။) = “အကြင်သူသည် ပညာရှိနှင့်တကွ မှီဝဲပေါင်းဖော်ရသဖြင့် ချမ်းသာခြင်းကို မျက်မြင်ဒိဋ္ဌရရှိ၏။(လက်တွေ့အကျိုးရရှိ၏။)” || “ယွံမၞးတံ၊ ဓဝ်သဒ္ဓါ ဓဝ်သဳလ ဓဝ်စာဂ ဓဝ်တံဂှ် ဇိုန်ကဵုဖဵုဂတမတ် မၞးတံ ညာတ်တြဟာ။” (ဇ—၁၉ဝ။ အစွောံ။) = “အိုသင်တို့၊ သဒ္ဓါတရား သီလတရား ပေးကမ်းစွန့် ကြဲခြင်း စာဂတရားဟူသော ဤတရားတို့သည် မျက်မြင်ဒိဋ္ဌအကျိုးပေးသည်ကို သင်တို့မြင်ကြ ကုန်၏လော။” || “ယွံဂမှဳတံ၊ ပူဂဵုဒြိုဟ်ကဵုမိတ်တုဲဂှ် ဒဒိုက်ပ္ဍဲဂတမတ် ပ္ဍဲပစ္စုပ္ပန် မဒးစသိုၚ်ရောၚ် ဟွံသေၚ်ဟာ” ကျာ်တြဲဂး။ (ဇ—၅၁၆။ အစွောံ။) = “ရဟန်းတို့၊ အဆွေခင်ပွန်းကို ပြစ်မှား သောသူသည် မျက်မှောက်ပစ္စုပ္ပန်­ ဒုက္ခကိုခံစားရသည် မဟုတ်လော။” || “ဒဒှ်ဗြဴတံမဒှ်ဒုဿဳ လဂှ် အဲထ္ၜးကဵုဂတမတ်ညိအဴ” ပြောဟိတ်ဂး။ (ဇ—၅၃၆။ အစွောံ။) = “မိန်းမတို့အကျင့်သီလ မရှိကြောင်းကို အကျွန်ုပ်သည် မျက်မြင်ဒိဋ္ဌပြပါအံ့။” || “သၟိၚ်ကၠဵုဝွံ ပညာညံၚ်ကျာ်ဂမျိုၚ်ကီုသွံ။ ဂွံပျးထ္ၜးကဵုညးဂတမတ် ဒဵုမအိုတ်သလှ်ေပၟာရောၚ်သွံ” သၟိၚ်ဂး။ (ဇ—၂၂။ အစွောံ။) = “ဤခွေး မင်းသည် ဘုရားရှင်ကဲ့သို့သော ပညာရှိ၏။ လူတို့ကို ယုံမှားသံသယကုန်သည်အထိ မျက်မြင်ဒိဋ္ဌ (လက်တွေ့) ပြသပေသည်တကား။”')
,(2922,3,1,'အောက်မျက်နှာပြင်။','ဂတာၜဳ = ရေအောက်မျက်နှာပြင်။ ရေအောက်ကြမ်းပြင်။ || ဂတာဇြဟ် = ချောက်တွင်းနက်၏အောက်ကြမ်းပြင်။')
,(2923,3,1,'ခြေဖဝါး။',null)
,(2924,3,1,'၁။ လက်ဖဝါး။',NULL)
,(2924,3,1,'၂။ သံလက်။ (ပရန်ပစ္စည်း)',NULL)
,(2925,3,1,'သစ်လက်ဝါး။ သစ်မျောက်လက်။ (= တဲကၞုဲ) (ပါဠိ—ဂန္ဓဗ္ဗဟတ္ထက)',null)
,(2926,3,1,'ညာဏ်ပညာ။','တၠဂတိ = ပညာရှိ။')
,(2927,3,1,'‘ဂတေဝ်ပး’ ရှု။',null)
,(2928,3,4,'ပူနွေးအောင်လုပ်သည်။ နွှေးသည်။','ဂတဴသွ = ဟင်းနွှေးသည်။')
,(2929,3,4,'၁။ လှည့်သည်။','ဂတးရံၚ် = လှည့်ကြည့်သည်။ နောက်လှည့်ကြည့်သည်။ || “သပဝ်ဂှ် ဂတးရံၚ်ညာတ်ကေတ်တုဲ တီဒဒှ်နာ်ရ။” (ဇ—၁၅၄။ အစွောံ။) = “ဂဠုန်သည် နောက်သို့ လှည့်ကြည့်လတ်သော် (နဂါးကို) မြင်၍ နဂါးဖြစ်ကြောင်းသိ၏။”')
,(2929,3,4,'၂။ လှန်သည်။ တစ်ဖက်မှ တစ်ဖက်သို့ လှန်သည်။','“ပလောအ်စဲလဝ်ဂှ် ဂတးလဝ်တုဲရ။” = “လှန်းထားသောအင်းကျီကို လှန်ထားပြီးပြီ။” || “စိၚ်ဂှ် ဗိုၚ်ကၠောန်ၜိုတ်ကဵုဓဇဲတံ နလပှ်ဂတးပၠောဆုတံဂှ်ရ။” = “ထိုဆင်သည် လက်သမားတို့ကို ဝိုင်းလုပ်ကိုင်ပေး၏။ နှာမောင်းဖြင့် သစ်တို့ကိုလှန်လှိမ့်ပေး၏။”')
,(2929,3,4,'၃။ ဆန့်ကျင်ဘက်အခြေသို့ ပြောင်းလဲသည်။','ကွေတ်ဂတးအာ = အယူပြောင်းလဲသွားသည်။ လညာတ်ဂတးအာ = အမြင်ပြောင်းလဲသွားသည်။ || “(ဇန်ဂမၠိုၚ်) ကုသဵုစိုတ်ဂှ် ဂတးအာတုဲ အကု သဵုစိုတ်ဂှ် ဇၞော်မောဝ်အာတုဲ ဂၠိုၚ်ကဵုလောဘ၊ ဒေါသ၊ မောဟလောန်ရ။” (ဇ—၇၇။ အစွောံ။) = “လူအပေါင်းတို့သည် ကုသိုလ်စိတ်မှပြောင်းလဲ၍ အကုသိုလ်စိတ်ကြီးထွားကာ လောဘ၊ ဒေါသ၊ မောဟတရားတို့ တိုးပွားကုန်၏။” “(ခမဳမွဲဂှ်) ကြဴဝွံ စိုတ်ဒိဋ္ဌဂတးအာတုဲ ဗဗေၚ်သ္ၚာဂှ် ကဵုကၠေံ ကျာ်တြဲတုဲ ဟီုဂရိုဟ်တဴကျာ်ရ။” (ဇ—၉၄။ အစွောံ။) = “တယောက်သောရဟန်းသည် နောက် ­စိတ်ပြောင်း၍ ဒိဋ္ဌိအယူကိုယူကာ မိမိ၏သပိတ်သၚ်္ကန်းတို့ကို မြတ်စွာဘုရားအားပေး၍ မြတ်စွာဘုရားအား ပြောဆိုကဲ့ရဲ့၏။” || “ဗြန်ညာတ်ဗ္ၜေံဂှ်တုဲ စိုတ်သဳလဂတးအာတုဲ (သၟိက်ဂွံဂစိုတ်စဖျုန် ပၠန်ရ။)” (ဇ—၃ဝဝ။ အစွောံ။) = “ဆိတ်ကိုမြင်သောကျားသစ်သည် သီလစောင့်လိုစိတ်သည် ပြောင်းလဲသွားကာ အသားကို သတ်စားချင်ပြန်၏။” || “ကာလမပြာ်ဒဒိုက်သတြုဂှ် သတြုဒး ဂတးဆာန်ဇကုပၠန်တုဲ ဂတးဒှ်မိတ်ရ။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “ရန်သူအား ဒုက္ခမှကယ်သဖြင့် ရန်သူကစိတ်ပြောင်း၍ မိမိအားချစ်ရပြန်၏။ မိတ်ဆွေအဖြစ် ပြောင်းလဲဖြစ်လာရ၏။”')
,(2930,3,1,'မိုးကြိုးသံ။ ထစ်ချုန်းသံ။','“ညံၚ်ဗရုဂတး မဗြုပ္ဍဲတံကတောဝ်ဂှ်ဒှ်တုဲ—။” (ဇ—၁၅၂။ အစွောံ။) = “နားရင်း­ မိုးကြိုးသံထစ်ချုန်းဘိသကဲ့သို့ဖြစ်၍—။”')
,(2930,3,3,'ထစ်ချုန်းသည်။','ဂဂဵုဂတး = မိုးကြိုးပစ်သည်။ မိုးထစ်ချုန်းသည်။')
,(2931,3,4,'ဦးလှည့်သည်။',null)
,(2932,3,4,'၁။ လှန်လှောသည်။','“အဲဂၠာဲဂတးဂတုန်ထောံ အလုံသ္ၚိမွဲတုဲကီုဂှ် လေဝ် အပေါတ်အဲဂှ် အဲဂၠာဲဟွံဆဵုဏီရ။” = “တစ်အိမ်လုံးကို လှန်လှောရှာဖွေပြီးဖြစ်သော်လည်း ငါ့ပစ္စည်းကို ငါရှာမတွေ့သေးပါ။”')
,(2932,3,4,'၂။ (စကား) ဗလောင်းဗလဲပြောသည်။','“ဍေံဂှ် ဟီုဂတးဂ တုန်အရေဝ် ဒှ်ဒၟံၚ်နာနာသာ်ရောၚ်။ အရေဝ်ကတိပါၚ်ဍေံဂှ် ပ္တေဟ်စဟွံဂွံရ။” = “သူက စကားကို အမျိုးမျိုးဗလောင်းဗလဲပြောတတ်တယ်။ သူ့ကတိစကားကို ယုံလို့မရဘူး။”')
,(2933,3,4,'ကိုယ်ကိုလှည့်သည်။','“ကောန်ၚာ်တြုံဂှ် အဃောလှိၚ်ဒၟံၚ် ဂတးဇကုရ။” = “ထိုကလေးသည် အိမ်ပျော်နေစဉ် ကိုယ်ကိုလှည့်သည်။” || “အဲကလောန်ဂၠိုၚ်ဒၟံၚ် ဂတးဇကုဟွံဂတာပ်ရ။” = “ငါအလုပ်များနေ၍ ကိုယ်ကိုတောင် မလှည့်အားပါ။”')
,(2934,3,4,'မြေလှန်သည်။',null)
,(2935,3,4,'ပြန်လှန်သည်။ ပြန်လှည့်သည်။',null)
,(2936,3,4,'(ပြောပြီးသောစကား၊ ပေးပြီးသောကတိစသည်ကို)ပြန်ဖျက်သည်။ ခုတစ်မျိုးနောက် တစ်မျိုးပြောသည်။','“ယွံမၞးတံ၊ ဟိုတ်သ္ဍိုက်ဒြာဲထဝ်နိဂြောဓတုဲ အဲကဵုလဝ်အဘယဒါန်တုဲရ။ နူအဲ ပ္တိတ်လဝ်ပါၚ် ကဵုလဝ်အဘယဒါန်တုဲ ဒဵုကဵုကၟိန်ဍုၚ်အဲလေဝ် ကဵုထောံကၠေံကဵုဒှ်ကီုရ သဘဴအဲဂတး ပါၚ်ဟွံမွဲရ” သၟိၚ်ဂး။ (ဇ—၁၂။ အစွောံ။) = “(အချင်းတို့)၊ ကြည်ညိုသဖြင့် နိဂြောဓသမင်မင်း အား ဘေးမဲ့အဖြစ်ကို ပေးအပ်၏။ ငါသည် မင်းအဖြစ်ကိုသော် စွန့်အံ့၊ ထိုပဋိညာဉ်ကိုမဖျက်” ဟုမင်းဆို၏။ (ညောင်ကန်)')
,(2937,3,4,'ဖောက်ပြန်သည်။ မူလအခြေအနေမှ ချွတ်ယွင်းပြောင်းလဲသည်။','“(ကာလမဒှ် ဝုတ်ဗၠာဲမၞုံကဵုစရာဲရုပ်ကီုလေဝ် ဇၞော်ဗျုအာတုဲ ဒှ်အာညံၚ်ဗီုကၞုဲဗျုကီုရ။) ကာယဝွံ ဍေံလေပ်ဂတး ပၠံၚ်ပၠန်တဴရောၚ်။” (ဇ—၄၁၁။ အစွောံ။) = “အပျိုလူလျိုအရွယ်­ လှပတင့်တယ်သော်လည်း အိုမင်းရင့်ရော်သောအခါ မျောက်အိုကဲ့သို့ဖြစ်သွားရ၏။ ဤခန္ဓာကိုယ်သည် ဖောက်ပြန်တတ်သော သဘောရှိ၏။”')
,(2938,3,4,'အသံကိုပြောင်းသည်။ အသံတုလုပ်သည်။','“မိက်ဂွံမိပ်ဝေၚ်တုဲ သၟတ်တြုံဂှ် ဂတးကၠေံရမျှာၚ်တုဲ ပညံၚ်ရမျှာၚ်မၞိဟ်ဗြဴရ။”= “အပျော်သဘောဖြင့် သူငယ်သည် အသံကိုပြောင်း ၍ မိန်းမအသံကဲ့သို့ အသံတုပြုလုပ်သည်။” || “တြုံသ္ကံသေဏာပတိ မတဴပ္ဍဲကမော်ဆုဂှ် ဂတး ကၠေံရမျှာၚ်တုဲ ပညံၚ်ရမျှာၚ်ကလော်(ရ။)” (ဇ—၅၂၇။ အစွောံ။) = “သေနာပတိ၏ အဖော် ယောကျာ်းသည် သစ်ခေါင်းထဲ­နေ၍ အသံကိုပြောင်း၍ တစ္ဆေအသံကဲ့သို့ပြု၏။” || “လထဴဂှ် (ပညံၚ်ဒေဝတဴဆုတုဲ) ဗဂေတ်ဂတးကၠေးရမျှာၚ်တုဲ သာ်ဝွံမဟီုရ—။” (ဇ—၉၈။ အစွောံ။) = “ထို ယောကျာ်းအိုသည် သစ်ပင်စောင့်နတ်ဟန်ဆောင်၍ အသံကိုပြောင်းကာ အသံတုလုပ်၍ ဤသို့ဆို ၏။”')
,(2939,3,4,'စကားပြင်ပြောသည်။ စကားပြောင်းသည်။',null)
,(2940,3,1,'ဆောက်ပုတ်။','လေံဂတေက် = ဆောက်ပုတ်။ လက်ကိုၚ်တုတ်။ လက်ရိုက်။ || “(ဣသိစၞာဲဂှ်) လေံဂတေက်မွဲ ပၞုက်လဝ်ပ္ဍဲသ္ၚာ ဂ္ဇံဒၟံၚ်ဒးရးရ။” (ဇ—၁၃၈။ အစွောံ။) = “ထိုရသေ့ကောက်သည် ဆောက်ပုတ်တစ်ခုကို သၚ်္ကန်းတွင်ဝှက်ပြီးလျှင် လျောက်ပတ် စွာထိုင်နေ၏။”')
,(2941,3,1,'လွှ။',NULL)
,(2941,3,4,'လွှနှင့်ဖြတ်သည်။','ဂတေက်အှ်ော = လွှနှင့်ထင်းဖြတ်သည်။')
,(2942,3,1,'နှံကောင်။',null)
,(2943,3,4,'မီသည်။ အချိန်မီသည်။','“အဲဒြေပ်ဗက်ဍေံ ဟွံဂတာပ်ရ။” = “သူ့ကို ကျွန်တော် ပြေးလိုက်၍ မမီပါ။” || “ဗောဓိသတ်သၟာတ္ၚဂှ် မၞုံပရှ်မွဲဖရိပ်ဇုက်လလဳဂှ် ထပှ်ဝါပန်ဂတာပ်ရ။” = “ဘုရားလောင်းလေသမားသည် လျှပ်တစ်ပြက်အတွင်း ခုနစ်ကြိမ်ပစ်လွှတ်နိုင်သော အမြန်နှုန်းရှိ၏။” || ဟွံဂတာပ်လအ် = မကြာမြင့်မီ။ “ခမဳဂှ် ကမြဴလွဳကဵုဝိပဿနာတုဲ ဟွံဂွံဂတာပ်လအ် ဂွံ အာစိုပ်ဒဒှ်အရှန်ရ။” = “ထိုရဟန်းသည် ဝိပဿနာကို ပွားများအားထုတ်ရာ မကြာမြင့်မီ ရ ဟန္တာအဖြစ်သို့ရောက်၏။”')
,(2944,3,4,'ခေတ်မီသည်။ မျက်မှောက်ကာလ အတွေးအခေါ် အခြေအနေစသည်တို့နှင့် လိုက်လျောကိုက်ညီသည်။',null)
,(2945,3,4,'အားရသည်။','“ဍေံကၠောန်ကလောန် ဇိုၚ်တဲဍေံအိၚ်ဇိၚ်ဗွဲမ လောန် အဲဟွံဂတာပ်စိုတ်ရ (ဟွံဂတာပ်ကဵုစိုတ်ရ။)” = “သူအလုပ်လုပ်သည်မှာ သူအလွန်ခြေ လက်နှေးကွေးသဖြင့် ကျွန်တော်အားမရပါ။”')
,(2946,3,4,'အချိန်မီသည်။ လက်ဦးမှုရရှိသည်။','“မၞိဟ်ယဲဂှ် အာစိုပ်ရုၚ်ဂဥုဲ ဂတာပ်တဲတုဲ ဂွံလမျီုရ၊ ဗတ်ရစိုပ်ရုၚ်ဂဥုဲ ဟွံဂတာပ်တဲဂှ် ဟွံဂွံလမျီုရ။” = “လူနာသည် ဆေးရုံသို့ အချိန်မီ ရောက်ရှိသဖြင့် အသက်ကိုရ၏၊ အကယ်၍များ ဆေးရုံသို့ အချိန်မီမရောက်ရှိခဲ့လျှင် အသက်ဆုံး ရှုံးရလိမ့်မည်။”')
,(2947,3,4,'အသက်မီသည်။ အသက်မကုန်ခင် အချိန်မီရောက်ရှိသည်။','“မၞိဟ်ယဲဂှ် ယဲ က္ဍၚ်ဒၟံၚ်ဗွဲမလောန် မၞးဟွံအာရံၚ်ဏီမ္ဂး မၞးဟွံဂတာပ်လမျီုရ။”= “လူနာသည် အသည်းအသန်ဖြစ် နေသည်၊ သင်သွားမကြည့်သေးလျှင် သင်အသက်မမီတော့ပါ။”')
,(2948,3,4,'အချိန်မီသည်။','“လိက်ဘာဒးကၠောန်ပ္ဍဲသ္ၚိဂှ် ကွးဘာတအ် ဒးကၠောန်ညံၚ်ဂွံဂ တာပ်အခိၚ်ရောၚ် အ္စာဟီုစၞောန်လဝ်ရ။” = “အိမ်စာများကို ကျောင်းသားများ အချိန်မီအောင် လုပ်ရမည်ဟု ဆရာညွှန်ကြားထားသည်။”')
,(2949,3,1,'(စာအုပ်စသည်၏) အဖုံး။','ဂတိုပ်လိက် = စာအုပ်အဖုံး။')
,(2950,3,4,'မျက်ခွံ။',null)
,(2951,3,4,'(ဥပစာ) မျက်စိမဖွင့်နိုင်အောင် အလွန်အိပ်ချင်သည်။',null)
,(2952,3,1,'ဂဏန်း။ လယ်ပုစွန်။',null)
,(2953,3,4,'ဆောင့်သည်။','ဂတီုဇိုၚ် = ခြေဆောင့်သည်။')
,(2954,3,4,'(ဝမ်းနည်းကြေကွဲလွန်း၍) ရင်ဘတ်စည်တီးသည်။','“သီုဍာ်ရမတ် မပေၚ်ဒၟံၚ်ဗၠၚ် မတ်ၜါဂှ်ဒှ်တုဲ တဲၜါဂတီုသြိုဟ်တိၚ်တိၚ်တုဲ ဂၞကျာ်ဂတေဝ်ယာံတဴရ။” (ဇ—၅၂၅။ အစွောံ။) = “မျက်တွင်းနှစ်ဖက်­ မျက်ရည်များဖြင့်ပြည့်လျက် မိဖုရားသည် လက်နှစ်ဖက်ဖြင့် ရင်ဘတ်စည် တီး၍ ရှိုက်ကြီးတငင် ငိုကြွေးလေ၏။”')
,(2955,3,4,'ပေါလောပေါ်သည်။','“ဆုကၠဂတဝ်လ္တူဍာ်ရ။” = “ကျွန်းသစ်သည် ရေတွင်ပေါလော ပေါ်သည်။')
,(2955,3,4,'ပေါလောပေါ်သည်။','“ကျာပိုက်သလောမ်ပ္တိုန်ဍာ်ဂှ် ထမှာဲပုၚ်ထမှာဲသွဂှ် ဂတဝ်တိတ်ဟဳစှ်ေအာ—။” (ဇ— ၂၈၄။ အစွောံ။) = “လေတိုက်ခတ်၍ ရေကိုကမ်းသို့ တက်စေသည်ရှိသော် ထိုထမင်းအိုးဟင်း အိုးတို့သည် ရေ­ပေါလောပေါ်မျောပါသွား၏။”')
,(2956,3,4,'ပေါ့ပါးစွာပေါ်သည်။ မနစ်မြုပ်ဘဲတည်သည်။','“(အနုဘဴတၞိၚ်ဗောဓိသတ်ဂှ်တုန်) ပ္ဍဲဒေါဝ်က္ဍိုပ်လ္ပးဂှ် ကဵုစူစုတ်လဝ်မုဟ်တၞိၚ်ဂှ်တုဲ ကဵုတက်စုတ်ဆမွဲလစုတ်ဂှ်တုဲ တၞိၚ်ဂှ် ကၠိုဟ်ခၠၚ်တ သာတ်စှ်ေအာတုဲ စှ်ေဂတဝ်သာၚ်ဒၟံၚ် ပ္ဍဲဍာ်ထးတေံရ။” (ဇ—၃၈၇။ အစွောံ။) = “ဘုရားလောင်း ၏အပ်၏အာနုဘော်ကား ပေတုံးအလယ်­ အပ်အစွန်းကို ထောၚ်ထားစေ၍ တစ်ချက်တည်းရိုက် ခတ်သည်ရှိသော် ထိုအပ်သည် ပေတုံးကိုဖောက်ထွင်း၍ ပေအောက်­ထားသော ရေခွက်ထဲ­ မနစ်မြုပ်ဘဲ ပေါ့ပါးစွာပေါ်၍တည်၏။”')
,(2957,3,4,'အော်သည်။',null)
,(2958,3,4,'အော်ခေါ်သည်။','“နူဇမ္ၚောဲ မိဂတေဝ်ကော်အဲရ။” = “အဝေးမှ အမေကျွန်မ ကို အော်ခေါ်သည်။”')
,(2959,3,4,'စိတ်ဆင်းရဲသည်။ သောကရောက်သည်။ (?)',null)
,(2960,3,4,'(ပျက်သည်ကို) ပြင်သည်။ ပြုပြင်သည်။','“မပ္တံဝါစဳမုဲမြဍေံတံဂှ် —— ယဝ်ဍေံလီု ထ္ၜီုတၟေက်အာသဒှ်မ္ဂး ကဵုညးဂတေဝ်ဂဟဵုတုဲ ကဵုပဠန်ကဵုတၠဒြဗ်ရမိဂ္ဂးရောၚ်။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ ဒုု။ ၄၈၈။ စန္ဒိမာမဟာထေရ်။) = “သူတို့၏ပဲခွပ်၊ ပုဆိန်၊ ဓါးမစသည်တို့သည် —— အကယ်၍ပျက်၊ တုံး၊ ပဲ့သွားသည်ရှိသော် ကောင်းအောင်ပြုပြင်၍ ပိုင်ရှင်အား ပြန်ပေးရမည်ဟူလို ၏။”')
,(2961,3,4,'မျက်ရည်ယိုသည်။ ငိုကြွေးသည်။','“သီုကဵုကလောဂမၠိုၚ် မဂတေဝ်ဒၟံၚ်ဍာ် ရမတ်ရ (ဗောဓိသတ်) လုပ်အာဂြိုပ်ဟေမဝန် ပခမဳဣသိ။” (ဇ—၁၇၃။ အစွောံ။) = “ဘုရားလောင်းသည် ဆွေမျိုးအပေါင်းတို့က မျက်ရည်စက်လက်ဖြင့် ငိုကြွေးစဉ်ပင်လျှင် ဟိမဝန္တာတော သို့ဝင်၍ ရသေ့ရဟန်းပြု၏။”')
,(2962,3,16,'(န) ကတ္တီပါ။','‘ဂတေဝ်ပးဇာထဝ်ဂရောပ်စိၚ်။’ (ဇ— ၂၇၆။ အစွောံ။) = ‘ဆင်အလွှမ်းတန်ဆာ ကတ္တီပါရွှေကွန်ယက်။’')
,(2963,3,4,'အသံထွက်၍ငိုသည်။ ငိုကြွေးသည်။','“(သၟိၚ်ဒးပကာဂစိုတ်ရဂးတုဲ) သီုလၞီလၞာ် စိုတ်ဗွဲမလောန်ဂှ် က္တဵုဒှ်တုဲ ဂၞကျာ်ဂတေဝ်ယာံတဴရ။” (ဇ—၉၅။ အစွောံ။) = “မင်းသေရတော့အံ့ ဟုဆို၍ မိဖုရားသည် ကြီးစွာသောပူပန်သောကဖြစ်၍သည်းစွာငိုကြွေး၏။”')
,(2964,3,1,'အင်းပျဉ်။ ကုလားထိုင်။ (ပါဠိ—ပဳဋ္ဌ)','“(သၟိၚ်မြာ်ထဝ်ဂှ်) လတူဂတဵုထဝ် သၟိၚ်ကဵု ဍုန်ဒၟံၚ်ရ။” (ဇ—၁၅၉။ အစွောံ။) = “မင်းသည် ရွှေဥဒေါင်းမင်းကို ရွှေအင်းပျဉ်ပေါ်­ နားစေ ၏။”')
,(2965,3,1,'ပျဉ်။ ပျဉ်ချပ်။ သစ်ချပ်။',null)
,(2966,3,1,'သင်ပုန်းကြီး။ (မွန်ဗျည်း၊ သရ၊ ဗျည်းသရတွဲ၊ အသတ်တို့ကို ရွတ်ဖတ်ရေးသားတတ်ရန် စီစဉ်ရေးသားထားသောစာ။)',null)
,(2967,3,1,'ကျောက်သင်ပုန်း။ (ကျောက်လွှာဖြင့်လုပ်ထားသော စာရေးရန်သင်ပုန်း။)',null)
,(2968,3,1,'တံကဲပျဉ်။ မှီရာတကဲပျဉ်။ အမှီ။ နောက်ခံ။ နောက်မှီ။ (ပါဠိ—အပေဿနဖလက)','“ဂတဵုဒလာဲဂှ် (စိၚ်ဂှ်)ၜေါတ်ထောံကၠေံတုဲ—။” (ဇ—၁၆၁။ အစွောံ။) = “(ထိုဆင်သည်) တံကဲပျဉ်ကိုနုတ်၍—။” (ညောင်ကန်)')
,(2969,3,1,'နောက်မှီ။ တကဲ။ (ပါဠိ—အပေဿန)',null)
,(2970,3,1,'အကြွေး။','မိက်ဂတှ် = အကြွေးတောင်းသည်။ လေဲဂတှ် = အကြွေးလျော်သည်။ ဇက်ဂတှ် = အကြွေးယူသည်။ ငွေချေးယူသည်။ တၠဂတှ် = အကြွေးရှင်။ အကြွေးချေးပေးသောသူ။ ညးမဇက်ဂတှ် = အကြွေးချေးယူသူ။')
,(2971,3,1,'၁။ သံသရာကြွေး။ အတိတ်ဘဝကပြုခဲ့သော အကုသိုလ်ကံအကျိုး ဆက်။',NULL)
,(2971,3,1,'၂။ နောင်ဘဝတွင် ပြန်လည်ပေးဆပ်ရန်အကြွေး။ သံသရာကြွေး။',NULL)
,(2972,3,1,'၁။ အပြား။ မျက်နှာပြင်ပြန့်သောအရာ။','ဂတှ်ေဆု၊ ဆုဂတှ်ေ = သစ်ပြား။ ဂတှ်ေတၟအ် = ကျောက်ပြား။')
,(2972,3,1,'၂။ အရပ်ဒေသ။','“ဂတှ်ေဒေသဂှ် မၞိဟ်မံၚ်အောန်တဴရ။” = “ထိုအရပ်ဒေသတွင် လူနေနည်းပါးသည်။”')
,(2972,3,1,'၃။ (ငွေ၊ ပိုက်ဆံ) ပြားစေ့။ တစ်ကျပ်၏ အပုံ (၁ဝဝ)ပုံ (၁)ပုံ။',NULL)
,(2972,3,9,'၁။ (ငွေ၊ ပိုက်ဆံ) ပြားကို ရေတွက်ရာတွင် သုံးသောစကားလုံး။','သၠုဲစှ်ဂတှ်ေ = ပိုက်ဆံဆယ်ပြား။')
,(2972,3,9,'၂။ (အဝတ်အစား) အထည်ကို ရေတွက်ရာတွင် သုံးသောစကားလုံး။','ပလောအ်ပိဂတှ်ေ = အင်္ကျီသုံးထည်။ || ဂၞိန်ၜါဂတှ်ေ = ထဘီနှစ်ထည်။')
,(2973,3,1,'ဈေးကွက်။',null)
,(2974,3,1,'လက်ဖနောင့်။',null)
,(2975,3,4,'ထုသည်။',null)
,(2976,3,1,'ဂဒူး။ ပက်ကလာ။',null)
,(2977,3,4,'ရိုက်နှက်သည်။ ဆော်ပလော်တီးသည်။','“ကောန်ၚာ်ဟီုဝါတ်ဂှ် အပါဍေံ ဂဒဲလဝ်ကဵုၜါပိ လစုတ်ရ။” = “ပြောဆိုရခက်သောကလေးကို သူ့အဖေက နှစ်ချက်သုံးချက် ဆော်ပလော်တီး ထားသည်။”')
,(2978,3,1,'ယာယီတဲ၊ တင်းကုပ်။ (?)',null)
,(2979,3,4,'၁။ နှောင့်နှေးသည်။ နှေးကွေးသည်။','“ဟာဲရာဇကုမ္ဘ၊ လအာဗှ်ေမဂဒေက်တဴဂှ် ပ္ဍဲ ဂြိုပ်ဇၞော်ဝွံဂှ် တ္ၚဲရပၟတ်ဂြိုပ်မတူကၠုၚ်ဂှ် သိက်မသ္ပဒးရော။” (၅၅ဝ။ ဇ—၃၄၅။ ဒု—၂၇၂။ အစွောံ။) = “အချင်းရာဇကုမ္ဘ၊ သင်တို့၏သွားခြင်းသည် နှေးလှစွာ၏။ ဤတောကို တောမီး လောၚ်သည်ရှိသော် သင်တို့သည် အဘယ်သို့ပြုကုန်မည်နည်း။” (၅၅ဝ။ ဒု—၇၅၆။ ညောင်ကန်။)')
,(2979,3,4,'၂။ ချို့သည်။ ချို့တဲ့သည်။ မပြည့်စုံဖြစ်သည်။ (ပါဠိ—ကုဏ္ဍတိ)','အဝဲဂဒေက် = အၚ်္ဂါချို့တဲ့သည်။ (ပါဠိ—အၚ်္ဂဝိကလ) || ဂဒေက်ပြဒ္ဒညာ = ထုံထိုင်းသည်။ ဉာဏ်ပညာနုန့်နှေးသည်။ ပညာချို့တဲ့သည်။')
,(2980,3,4,'ဖြည်းနှေးသည်။ နှောင့်နှေးသည်။ ကြန့်ကြာသည်။','“ဟာဲရာဇကုမ္ဘ၊ ယြဴပူဂဵုမွဲ မပ္တုဲစရၚ်ကိစ္စမွဲမွဲ ပ္ဍဲကာလမဂဒေက်ဍိုန်ဂှ် ပ္ဍံပ္တုဲပြဟ်ရ၊ ဟိုတ်မပ္တုဲပြဟ်ဂှ် မဂဒေက်ဍိုန်အာရ။” (၅၅ဝ။ ဇ—၃၄၅။ ဒု—၂၇၂။ အစွောံ။) = “အချင်းရာဇကုမ္ဘ၊ အကြင်သူသည် အမှုကိစ္စတစ်ခုကို ပြုရာ­ ဖြည်းဖြည်းညှင်းညှင်း ပြုအပ်သောကာလ­ လျင်မြန်စွာပြု၏၊ လျင်မြန်စွာပြုသဖြင့် အ မှုကိစ္စသည် နှောင့်နှေးကြန့်ကြာသွားရ၏။”')
,(2981,3,4,'နှုတ်ကို(ပါးစပ်ကို) နှောင်ဖွဲ့သည်။','‘မန်မဂဒေက်ပါၚ်သတြု’ (၅၅ဝ။ ဇ—၃၆၈။ ဒု—၃၃၇။ အစွောံ။) = ‘ရန်သူ၏နှုတ်ကို နှောင်ဖွဲ့သောမန္တရား။’ || “လၟာဲမွဲဂှ် နဂဥုဲမန်ဍေံဂှ် ဍေံဂဒေက်ကၠေံပါၚ်ဇြုံဂှ်တုဲ ဍေံရပ်ဏာ အာဗလးကၠေံ ပ္ဍဲဂြိုပ်တေံရ။” (၅၅ဝ။ ဇ— ၄ဝ၂။ ဒု—၄၇၄။ အစွောံ။) = “တစ်ယောက်သော အလမ္ပာယ်သည် မြွေ၏ခံတွင်းကို (ဆေး မန္တန်ဖြင့်) ဖွဲ့ခြင်းကိုပြု၍ မြွေကိုယူ၍ တော­လွှတ်၏။” (၅၅ဝ။ တ—၂၈၄။ ညောင်ကန်။)')
,(2982,3,4,'၁။ (အာနုဘော်၊ အာနိသင်စသည်) မထင်ရှား မပေါ်လွၚ်ဖြစ်သည်။ မှေးမှိန်သည်။ ကွယ်ပျောက်သည်။','“နအနုဘဴဗောဓိသတ်(သၟိၚ်ကုသ)ဂှ် ကာလဗောဓိသတ် လုပ်စိုပ်ဂၞကျာ် (ပြဘာဝတဳ) တုဲဂှ် လျးဂၞကျာ်ဂှ် ဂဒိုက်အာတုဲ ဒ္ဂေတ်ဗက်အာဒမၠုရောၚ်။” (ဇ—၅၃၁။ အစွောံ။) = “ဘုရားလောင်းကုသမင်း၏ ဘုန်းအာနုဘော်ကြောင့် ကုသမင်းက ပဘာဝတီမိဖုရားထံသို့ ဝင် ရောက်သောအခါ မိဖုရား၏ ကိုယ်အလင်းရောင်သည် မှေးမှိန်ကွယ်ပျောက်၍ အမှောင်နှင့်ယှဉ်၏။”')
,(2982,3,4,'၂။ (ဉာဏ်၊ ပညာ) ထိုင်းသည်။ နုံ့သည်။ ထိုင်းမှိုင်းတွေဝေသည်။','“(မၚ်ဗၠာဲဂှ်) ဂဒိုက် သ္ဒိုဟ်လောန်၊ ကၠောန်ၜိုတ်တံဇိုၚ်အ္စာတုဲ ကတ်ရ၊ ပဟိုတ်မဂဒိုက်ဂှ်ရ ဇၟာပ်ကွတ်ကေတ်ဟွံဂွံ ဟေၚ်။” (ဇ—၁၂၃။ အစွောံ။) = “ထိုလုလင်သည် ထိုင်းမှိုင်းတွေဝေ၏။ ဆရာ့ခြေရင်း­ လုပ်ကိုင်ပေး၍ အတတ်သင်၏။ ဉာဏ်ထိုင်းသည်၏ အဖြစ်ကြောင့်ကား သင်ခြင်းငှာမတတ်နိုင်။” || “သၟတ်ကောန်သၟိၚ်ဝွံ — မၞုံညာန်မဂဒိုက်လောန်။” = “ဤမင်းသားငယ်သည် အလွန်လျှင်ဉာဏ်နုံ့၍ ထိုင်းမှိုင်းတွေဝေ၏။” ‘သဒီုဂဒိုက်’ လည်းရှု။')
,(2984,3,4,'ဉာဏ်ထိုင်းသည်။ ဉာဏ်တုံးသည်။ နုံ့နှေးသည်။',null)
,(2985,3,4,'နှုတ်ဆွံ့သည်။—စေသည်။','“အမှုအရာမသ္ဒဟ်ဒတုဲမြမောဝ်ညး လ္ပဂဒိုက်ပါၚ်ကဵုဂ လာန်ညိ။ (ဟီုပ္တိတ်ဗိုန်န်ညိ။)” (ဇ—၄။ အစွောံ။) = “သူတစ်ပါးအကျိုးစီးပွားဖြစ်မည့်အကြောင်း အရာကို နှုတ်မဆွံ့ဘဲ ပြောဖြစ်အောင် ပြောထုတ်ပါလေ။” || “မူဟိုတ်တၠအဲတံ ဂဒိုက်ကၠေံပါၚ် ကောန်အဲ ဟွံကဵုပံက်ပါၚ်ကဵုအဲဍိက်ဗြဴရောလေဝ် ဒေဝတဴတံ။” (ဇ—တေမဳ။ အစွောံ။) = “အကျွန်ုပ်သားကို နှုတ်ဆွံ့လေအောင် အကျွန်ုပ်အားနှုတ်မဖွင့်ရလေအောင် အဘယ်ကြောင့်သင်တို့ ပြုထားကြကုန်ဘိသနည်း အိုနတ်ဒေဝါအပေါင်းတို့။”')
,(2986,3,1,'ပုခုံး။',null)
,(2987,3,1,'၁။ မြစ်ပျဉ်း။ သစ်ပင်မုတ်ဆိတ်။',NULL)
,(2987,3,1,'၂။ ကာလက်နက်တစ်မျိုး။','(‘ဒိုင်း’ သို့မဟုတ် ‘လွှား’ ဖြစ်နိုင်ဖွယ်ရှိသည်။ ‘ဂဒံၚ်ဂဒါၚ်’ ဟူ၍ တွဲသုံးလေ့ရှိသည်။)')
,(2988,3,1,'အငူ။','တီပ္ညုၚ်ဂဒုၚ် = (ဥပစာ) ပင်လယ်ရေကြောင်းခရီး­ ကျွမ်းကျင်လိမ္မာသည်။')
,(2989,3,1,'ဒိုင်း။ လွှား။ ကာ။',null)
,(2990,3,1,'(ကြက်၊ ငှက်စသည်၏) အမြီးတောင်။ အမြီးစွန်း။','“(မြာ်ကၟက်ဂှ်) သောၚ်ပတိုန် ဂဒံၚ်ဍုတ်တုဲ လှ်ေထ္ၜးကဵုညးရ။” (ဇ—၃၂။ အစွောံ။) = “ထိုဥဒေါင်းဖိုသည် အမြီးတောင်ကိုဖြန့်၍ ကပြ၏။”')
,(2991,3,4,'(ဆင်၊ မြင်း၊ ခွေး၊ ကြောင်စသည်) နားရွက်ကိုကားသည်။','“စိၚ်ကၠေၚ်မိၚ်ဂလာန်စၟစၚ်စေဝ်အသုဘဂှ်တုဲ ပကိုၚ်ဗတ ဂဒိုၚ်ပ္တိုန်ကတောဝ်ၜါတုဲ ကလေၚ်ကၠုၚ်—။” (ဇ—၂၂၇။ အစွောံ။) = “အမုန်ယစ်သောဆင်ပြောင်သည် မစင်ပိုး၏ (စိန်ခေါ်သော) စကားကိုကြား၍ အမြီး ကိုထောၚ်လျက် နားရွက်နှစ်ဖက်တို့ကိုကားလျက် ပြန်လှည့်လာ၏။”')
,(2992,3,4,'ကျေးဇူးကန်းသည်။ ကျေးစွပ်သည်။',null)
,(2993,3,4,'ဥပေါက်အောင်ဝပ်သည်။','“စာၚ်ဂဒပ်ဒၟံၚ်ရ။” = “ကြက်ဥဝပ်နေပြီ။”')
,(2994,3,1,'အခန်း။','ဂဒမ်စပုၚ် = ထမင်းစားခန်း။')
,(2995,3,4,'ရှိမြဲအတိုင်း ဆက်လက်တည်ရှိစေသည်။ ထိန်းသိမ်းသည်။ စောင့်ထိန်းသည်။','“(ပိလိယသေဋ္ဌဳ ပိုန်ဟုတ်ဒိုက်အာ) အာစိုပ်မိတ်ဆာန် ပိုန်ဒြပ်သီုဍိက်သ္ကံ သၟဟ်ဂလိုၚ်ဂွံနၚ် ဂွံဂဒီု လဝ်ပိုန်ဟာန်ပၠန်။” (ဇ—၁၃၁။ အစွောံ။) = “(စည်းစိမ်ဥစ္စာများ ဆုံးရှုံးသွားသော ပီဠိယသူဌေးသည်) ချစ်သောအဆွေခင်ပွန်းဆီရောက်၍ ကျေးကျွန်များနှင့်တကွ စည်းစိမ်ဥစ္စာ ထက်ဝက်ကိုရ လာခဲ့၍ မိမိ၏စည်းစိမ်ဥစ္စာကို ပြန်လည်ထိန်းသိမ်းနိုင်ခဲ့၏။” || “အဲဓညဓဝ်မိတ်မသလီု သဂဒီုပ္တန် လဝ်ဓဝ်မိတ်ရ စွံစိုတ်တုဲ—။” (ဇ—၁၃၁။ အစွောံ။) = “ငါသည် အဆွေခင်ပွန်းတရား ပျက်မည် စိုး၍ အဆွေခင်ပွန်းတရားကို တည်စိမ့်သောငှာ စောင့်ထိန်းမည်ဟု သဘောထား၍—။”')
,(2996,3,1,'ကတိုးကောင်။',NULL)
,(2996,3,4,'၁။ ကျပ်တင်သည်။','“ဂဒဵုလဝ်ကလ္တူနာၚ်ရ။” = “ငါးကို ကျပ် ခိုးစင်ပေါ်တွင် ကျပ်တင်ထားသည်။”')
,(2996,3,4,'၂။ ဖုံးသည်။ (‘လဒဵု’ ဟုလည်းရေးသည်။)','‘ဂဒဵုလဝ်လၟဳထၟာဲ’ = ‘အိုးအဖုံးကို ဖုံးထားသည်။’ || ‘သၟိၚ်ကုသဂဒဵုလဝ်မုက် နဍောၚ်ဒကှ်’= ‘ကုသမင်းသည် ကြာပန်းပွင့်ဖြင့် မျက်နှာဖုံးထား၏။’ || “ဂၞကျာ်ဝွံ ဒုဟ်ဇကုနွံဂဒဵုလဝ် အဲဟၟဲကဵုဒုဟ်ဂှ် ဂၠာဲတၚ်ဒုဟ် အဲရောၚ်သွံ” ပြောဟိတ်ချပ်။ (ဇ—၂၂ဝ။ အစွောံ။) = “ဤမိဖုရားသည် မိမိ­ရှိသောအပြစ်ကို ဖုံးကွယ်၍ အပြစ်မရှိသောငါ့ကို လုပ်ကြံအပြစ်ဖို့ဘ၏” ဟုပုရောဟိတ်ကြံ၏။')
,(2997,3,4,'စကားထာဝှက်သည်။',null)
,(2998,3,1,'အဖူး၊ အငုံ။',NULL)
,(2998,3,4,'(ငှက်ပျောပင်၊ အုန်းပင်စသည်) အဖူးထွက်သည်။','“တၞံဗြာတ်တဵု လဝ်ဂှ် ဂဒအ်ဒၟံၚ်ဣရ။” = “စိုက်ထားသောငှက်ပျောပင်သည် အဖူးဖူးနေပြီ။”')
,(2999,3,1,'၁။ ငှက်ပျောဖူး။ (အပင်)',NULL)
,(2999,3,1,'၂။ ခြေသလုံး။',NULL)
,(2999,3,1,'၃။ ငှက်ပျောဖူး။ (စေတီအစိတ်အပိုင်း)',NULL)
,(3000,3,1,'၁။ ရေလမ်းတွင် တစ်နေရာမှ တစ်နေရာသို့ ပို့ဆောင်သောလှေသၚ်္ဘော။ ယင်းသို့ပို့ဆောင်သောသူ။ ကူးတို့သည်။','“(ဗောဓိသတ်) ကၠုၚ်စိုပ်သြၚ်ကြုၚ်ဂှ် ဒစာံကသာပ်ကဵု ကုဂဒိုအ်တုဲ ဍိုက်ဂၠုၚ်ရ။” (ဇ—၃။ အစွောံ။) = “ဘုရားလောင်းသည် မြစ်ဆိပ်သို့ရောက်သော် ကူးတို့သည်အား ရှစ်သပြာကိုပေး၍ လှေစီး၏။”')
,(3000,3,1,'၂။ ကျင်ငယ်စွန့်ရာအရပ်။','ထၟာဲဂဒိုအ် = နောက်ဖေးအိုး၊ “ပဟိုတ်ကဵုဒြာဲဗြဴမစကၟတ် သုၚ်ဍာ်ပတ်သြဴ ပ္ဍဲဂဒိုအ်ဣသိဂှ်တုဲ တန်အာဂၠံဂဝ် ရ။” (ဇ—၅၂၆။ အစွောံ။) = “တစ်ခုသောသမင်မသည် ထိုရှင်ရသေ့ ကျင်ငယ်စွန့်ရာအရပ်­ (သုက်နှင့်ရောသော)မြက်ကိုစား၍ ကျင်ငယ်ရေကို သောက်ခြင်းကိုစွဲ၍ ကိုယ်ဝန်တည်၏။”')
,(3001,3,10,'(န) မြည်းသတ္တဝါ။','(မွန်ဝေါဟာရ ‘ချး’/‘မာဲ’ တို့နှင့်အတူတူ။) ‘ဂတ်ဒြဘ’ ရှု။')
,(3002,3,1,'ပျဉ်းမပင်။',null)
,(3003,3,4,'ချောၚ်ကျသည်။','“သ္ၚိပိုဲဂှ် နွံပ္ဍဲဍာန်ဇၞော်ဟွံသေၚ်၊ နွံပ္ဍဲဂၠံၚ်သၟတ် ဂနုက်ဒၟံၚ်ရ။” = “ငါတို့အိမ်သည် လမ်းမကြီး­ တည်ရှိသည်မဟုတ်၊ လမ်းငယ်­တည်ရှိ၍ ချောၚ်ကျနေသည်။”')
,(3004,3,1,'အိမ်ဈေးသည်။ (ပါဠိ—ပါပဏိက)',null)
,(3005,3,1,'တညင်းသီး။ (မြန်မာဝေါဟာရ ‘တညင်း’သည် မွန်ဝေါဟာရ ‘ဒနေၚ်’ မှ ဆင်းသက်လာသည်။)',null)
,(3006,3,1,'ဝါးတစ်လုံးလှေခါး။','‘ဂၞံၚ်’ ရှု။')
,(3007,3,16,'‘ဂၞံၚ်ဂၞာတ်—၁’၊ ‘ဂၞံၚ်ဂၞာတ်—၂’ ရှု။',null)
,(3008,3,1,'ဂဏန်းသင်္ချာ။',null)
,(3009,3,1,'လိုအၚ်ဆန္ဒ။','ဒးဂၞပ် = သဘောကျသည်၊ ကြိုက်နှစ်သက်သည်။')
,(3010,3,1,'၁။ အစွယ်။','၂။ ခြေဖနောင့်။')
,(3011,3,1,'မြွေပါ။ (‘ဇၞးဇာတ်’ ဟုလည်းရေးသည်။)',null)
,(3012,3,1,'ဂုံညင်း။','ဂနေအ်က္ၜံၚ် = ဒူးဆစ်ဂုံညင်း။')
,(3013,3,4,'(ထမင်း) ပျော့လွန်းသည်။','“ပုၚ်မွဲထမှာဲဂှ် လ္ၚဵုသ္ၚုလ္ၚဵုဂပေက်။” (ဇ—၇၇။ အစွောံ။) = “တစ်အိုးတည်း­ ချက်သောထမင်းသည် အချို့သည် မကျက်နပ်၊ အချို့သည် အလွန်ပျော့၏။”')
,(3014,3,4,'လှုပ်ရှားသည်၊ လူးလွန့်သည်၊ ဆတ်ဆတ်တုန်သည်။','“ကဂှ် ကၠာဟွံချိုတ် ဂပိုတ်ဒၟံၚ်ဗွဲမလအ်ရ။” = “ထိုငါးသည်မသေမီ ကြာရှည်စွာ တဆတ်ဆတ်တုန်လှုပ်နေသည်။”')
,(3015,3,4,'လူးလဲသည်။ လူးလွန့်သည်။ မခံမရပ်နိုင်အောင် ဝေဒနာပြင်းထန်စွာ ခံစားရသည်။','“မၞိဟ်ယဲဂှ် ဒုက္ခဝေဒနာရာန်သကိုတ်တုဲ ဒးဂပိုတ်ဂပိုၚ်ဒၟံၚ်ရ။” = “လူနာသည် ဒုက္ခဝေ နာနှိပ်စက်၍ တဖျတ်ဖျတ်လူးလွန့်နေရသည်။”')
,(3016,3,4,'ပျာယာခတ်သည်။ လူးလာခေါက်ပြန် လှုပ်ရှားသည်။','“လဗြဴဂှ် စၟဳမၚ်ဒၟံၚ်တၠုၚ် ကောန်ဂှ်တုဲ လလအ်ကောန်ဂွံစိုပ် ဒၟံၚ်ဟွံတန် လုပ်အပ္ဍဲမွဲလစုတ် တိတ်မ္ၚးမွဲလစုတ် ဂပိုတ်ခရိုတ် ဒၟံၚ်ရ။” = “အဖွားအိုသည် သား၏အလာကို စောင့်မျှော်နေရာ သားရောက်မလာမချင်း အငြိမ် မနေနိုင်ဘဲ အထဲဝင်လိုက် အပြင်ထွက်လိုက်နှင့် လူးလာခေါက်ပြန် လှုပ်ရှားနေသည်။”')
,(3017,3,1,'အသိုက်။ အသိုက်အမြုံ။','‘ခပေဲါ’ ရှု။')
,(3018,3,1,'အကွေ့။','ဂပဝ်ဂၚ်၊ ဂပဝ်ကြုၚ် = မြစ်ကွေ့။ ဝင်ဂပဝ် = ဝင်္ကပါ။')
,(3018,3,4,'လှည့်ပတ် ၍သွားသည်။ လှည့်ပတ်ရှောင်ကွင်း၍သွားသည်။','“ဇၞတ်ၜိုၚ်လှေအ်ဏာတုဲ (လၟ) အာသ္ၚောဲလောန် ရဂးတုဲ ၜိုၚ်ဒြေပ်ဂပဝ်ကၠုၚ် (ရီုဗလးတဴကၞုဟ်ဂှ်ရ။)” (ဇ—၂ဝ၆။ အစွောံ။) = “သမင်သည် မုဆိုးအား သွေးဆောင်ခေါ်သွားရာ မုဆိုးသည် အလွန်ဝေးပြီဟု သမင်သည် လှည့်ပတ်ရှောင်ကွင်း ၍ ပြေးလာပြီးလျှင် လိပ်ကို ကူညီကယ်လွှတ်၏။”')
,(3019,3,3,'လက်ယာရစ်လည်သော။','ကၞုသၚ်ဂပဝ်သ္တုံ (ဇ—၂၈၃။ အစွောံ။) = လက်ယာရစ် လည်သောခရုသင်း။')
,(3020,3,1,'(ကျောက်၊ သစ်စသည်) အပြား။ အချပ်။','ဂပှ်ေတၟအ် = ကျောက်ပြား။ ကျောက်ချပ်။ “ဒေဝဒတ်ပၠောဖျေံတၟံဂှ်ရ။ ကာလဂှ် ကၞောတ်တၟံၜါမစပ်ဒၟံၚ်ဂှ် ဒစးဒုၚ်တၟံဇၞော်ဂှ်တုဲ ဂပှ်ေတၟံဇၞော်ဂှ် ပါ်အာတုဲ စှ်ေဒွံဒးၝောံဇိုၚ်ကျာ်တုဲ ဆီတိတ်အာ။” (ဇ—၅၃၃။ အစွောံ။) = “(ဒေ ဝဒတ်သည် ထိုကျောက်တုံးကို လှိမ့်ချ၏။) တောင်ထွတ်နှစ်ခုတို့သည် တကွလာလတ်ကုန်၍ ထိုကျောက်ကို ခံလင့်ကုန်၏။ ထိုကျောက်မှ ကျောက်ချပ်လွှာသည် ကွာ၍ ဘုရားသခင့်ခြေမတော်ကို ခတ်မိ၍ သွေးကိုဖြစ်စေ၏။” (ညောင်ကန်)')
,(3020,3,4,'ပြားချပ်သည်။','“တၟအ်ဂှ် ဂပှ်ေဒၟံၚ်ရ။” = “ထိုကျောက်သည် ပြားချပ်နေသည်။”')
,(3021,3,4,'တွေ့ဆုံသည်။','ဂဗဆဵု = ကြုံတွေ့သည်။')
,(3022,3,1,'သင်းခွေချပ်။','(ကြိ) ကပ်စေးနဲသည်။')
,(3023,3,4,'စေးနှဲသည်။ ဝန်တိုစဉ်းလဲသည်။','“ပူဂဵုမဒြိုဟ်သ္ကာတ်လောန် ဓဇန်သဟာသဳဂှ်ကီု၊ ပူဂဵုဂဗိဂမ္တက်လောန်တံဂှ်ကီု မစှ်ေစိန်ဒၟံၚ် ပ္ဍဲနရက်ဇမ္ကာတ်ဂှ်ရ။” (၅၅ဝ။ ဇ—၅၃ဝ။ ၉—၁ဝ၇။ အစွောံ။) = “အလွန်ကြမ်းကြုတ်ရက်စက်သော သူတို့သည်၄င်း၊ အလွန်စေးနှဲဝန်တိုသော သူတို့သည်၄င်း ထိုပြင်းထန်သောငရဲ­ ကျခံကြရကုန်၏။” ‘ဂမ္ဗိဂမ္တက်’ ရှု။')
,(3024,3,4,'ဖြူစင်သန့်ရှင်းအောင်လျှော်ဖွပ်သည်။','“ယာတ်ဂှ် ကဵုဂဗုစအးတုဲ ဒေပ်လဝ်။”(ဇ— ၁၄၇။ အစွောံ။) = “ထိုအဝတ်ကို ဖြူစင်သန့်ရှင်းအောင် လျှော်ဖွပ်၍ သိမ်းထား၏။”')
,(3025,3,4,'ပါးရိုက်သည်။ (အထူးသဖြင့် မျက်နှာကို) ရိုက်သည်။ ပုတ်သည်။','ဒးဂဗး = ပါးရိုက် ခံရသည်။ “ဂစေံဓဇဲတီလၟဂှ်တိတ်တုဲ ဗြုတုဲ နကဵုသၞေၚ်ဂှ် ဂဗးစုတ်မုက်လၟ—။” (ဇ—၂ဝ၆။ အစွောံ။) = “ခေါက်ရှာငှက်သည် ထိုမုဆိုးထွက်သည်၏အဖြစ်ကိုသိ၍ မြည်လျက် အတောင်ကိုခါ ပြီးလျှင် — ထိုမုဆိုးကို မျက်နှာ­ပုတ်၏။” (ညောင်ကန်)')
,(3026,3,4,'အလျင်စလိုလုပ်သည်။','ဂဗက်ကၠုၚ် = အလျင်စလိုလာသည်။ ဂဗက်ကၠောန် = အလျင်စလိုလုပ်သည်။')
,(3027,3,5,'အလျင်စလို၊ အဆောတလျင်။',null)
,(3028,3,1,'စာရေးစားပွဲငယ်။ အိမ်သုံးစားပွဲငယ်။',null)
,(3029,3,4,'ဖုန်။ မြေမှုန်။','ဂဗိုက်က္တဵု၊ ဂဗိုက်ဂၠု = ဖုန်ထသည်။ “ဍုၚ်သွဝ်တေံဂှ် ဟွံမွဲကဵုသရီု လက်ကၠိုက်ဂဗိုက်တိ—။” (ဇ—၂၄၃။ အစွောံ။) = “နတ်ပြည်­ ရွှံ့ညွန်ဖုန်မှုန့်မြေမှုန့်မရှိ။”')
,(3030,3,4,'ဖွဲနု။',null)
,(3031,3,1,'ချောက်။','ဂဗၚ်ဒဵု = တောင်ချောက်။')
,(3032,3,4,'ရံသည်။','“မံၚ်မတအ် ဂဗါၚ်လဝ်ဂၞကျာ်ရ။” = “မောင်းမအခြွေအရံတို့ မင်းသမီးကို ရံထားကြသည်။”')
,(3033,3,4,'မှုန်ရီသည်။ ရေးရေးမြင်သည်။',null)
,(3034,3,5,'မှုန်မှုန်ရီရီ။',null)
,(3035,3,1,'ဗွက်၊ ရွှံ့ညွန်။',null)
,(3036,3,1,'အမြစ်ရင်း။ အစွယ်ရင်း။','“လၟအလံၚ်ဒေဝဒတ်ဂှ် ကုတ်ကေတ်ကၠေံ ဒြၚ်သၟိၚ်စိၚ်ဆဒ္ဒန် ဒဵုကဵုတမ်ဂဗိုၚ်ရ။” = “ဒေဝဒတ်လောင်းမုဆိုးသည် ဆဒ္ဒန်ဆင်မင်း၏အစွယ်ကို အစွယ်ရင်းအထိ ဖြတ်ယူလိုက်၏။”')
,(3037,3,4,'(သစ်ပင်)ခုတ်လှဲသည်။',null)
,(3038,3,4,'တိုက်သည်။ ထိသည်။',null)
,(3039,3,1,'အမှုအခင်း။ အငြင်းအခုံ။','ပ္တုဲဂဗုတ်၊ သ္ဂုတ်သွာတ်ဂဗုတ်၊ စဳရေၚ်ဂဗုတ်အမှု = အမှုစီရင်ဆုံးဖြတ်သည်။ တရားဆုံးဖြတ်သည်။ “ယြဴသၟိၚ်မွဲ ဟွံစဳစတ်တုဲ မပ္တုဲကဵုဂဗုတ်ညးဂှ် သၟိၚ်ဂှ် ဟွံဆာဲရ။” (ဇ—၃၃၂။ အစွောံ။) = “အကြင်မင်းသည် မစုံစမ်းမစစ်ဆေးမူဘဲ တရားဆုံးဖြတ်၏၊ ထိုမင်းသည်မကောင်း။” ‘ပဂဗုတ်’ (ကြိ) လည်းရှု။ ‘အမှု—၂’ (န)နှင့် အဓိပ္ပါယ်အတူတူ။')
,(3040,3,1,'ကြောင့်ကြမှု။ ကြောင့်ကြရသောအလုပ်။ ပလိဗောဓ။','“ယွံၝောံ၊ ပစ္စေဂဗုတ်ပန်ဂှ် ထောံကၠေံသ္ၚိကၟိန် ကၟိန်ဍုၚ်ယဿပတ်တုဲ မတိတ်ပခမဳ ဟၟဲကဵုဂဗုတ်ဂှ် နတသိုက် မဂွံစသိုၚ်တဴ အိုတ်ရ။” (ဇ—၄ဝ၈။ အစွောံ။) = “ရှင်မ၊ ဤလေးဆူကုန်သော ပစ္စေကဗုဒ္ဓာတို့သည် မင်းအဖြစ်ကိုစွန့်၍ ရဟန်းပြု၍ ပလိဗောဓမရှိကုန်သည်ဖြစ်၍ ချမ်းသာသဖြင့် လွန်စေကုန်၏။”(ညောင်ကန်) || “ဟာဲသဟာဲ (ခ္ဍာ်) မသၟဟ်ကေုာံပိုဲ၊ အဲစက္ကဝက် ဝေၚ်အာနူအိက်ၚာ်ကဵုသွန်ဂှ်ဒှ်တုဲ ဖျုန်မစပ်ကဵုသတ်ပ္ဍဲဒဵု ဖျုန်မစပ်ကဵုသတ်ပ္ဍဲဍာ် အဲဟွံပပြဘိုက်ရ။ စၞမအောန်ကဵုဂဗုတ် စၞသာ်ဂှ် မဒှ်ဘော ဇိုန်အဲရ။” (ဇ—၄၅၁။ အစွောံ။) = “အဆွေကျီး၊ စက္ကဝက်ငှက်ဖြစ်သောငါသည် ရေညှိရေမှော်မှတစ်ပါး ကုန်းသတ္တဝါတို့၏အသားကို၄င်း၊ ရေသတ္တဝါတို့၏အသားကို၄င်း ငါမသုံးဆောင်။ ထိုသို့ ကြောင့်ကြမှုနည်းသော အစာမျိုးသည်သာ ငါ၏အစာဖြစ်၏။” ‘မသက္ကုဂဗုတ်’ လည်းရှု။')
,(3041,3,1,'တရားရုံးနှင့်ဆိုင်သောအမှု။ အမှုအခင်း။ အငြင်းအခုံ။','“အပ္ဍဲဍုၚ်ကီု မ္ၚးဍုၚ်ကီု ဇန်တံဒှ်ဂဗုတ်ဂလာန် ကတဴကတာန် ဟီုဗျိပၠုတ်သီုဖအိုတ်ဂှ် ဟွံမိၚ်သက်သက်ရ။ ဂလာန်ထိုင်သးဂှ် နွံရ။” (ဇ—၁၅၁။ အစွောံ။) = “မြို့တွင်း­၄င်း မြို့ပြင်­၄င်း လူတို့သည် အမှုအခင်းဖြစ်ပွား ခြင်း၊ ဆူပူခြင်း၊ အပြစ်တၚ်ရှုတ်ချပြောဆိုခြင်းဟူ၍ လုံးဝမကြားရ။ ချီးမွမ်းသောစကားသာလျှင်ရှိ၏။” || “မၞိဟ်တံဂမၠိုၚ်ဂှ် ဍေံက္တဵုဗဒှ်ဂဗုတ်ဂလာန်ကေုာံရၚ်သ္ကံဂှ် ဍေံပၠေၚ်ဇကုဍေံ ဍေံဖျိုက်ကဵုသၟိၚ်တံရောၚ်။ ဍေံမဗပေၚ်ကဵုတိုက်ဖလှူသၟိၚ်တံရောၚ်။” (ဇ—၄ဝဝ။ အစွောံ။) = “လူအပေါင်းတို့သည် အချင်းချင်း အငြင်းအခုံဖြစ်ခြင်းကြောင့် မိမိကိုမိမိဖြုန်းတီး၍ မင်းတို့ကိုသာ ချမ်းသာစေ ၏။ မင်း၏ဥစ္စာတိုက်ကို တိုးပွားစေ၏။” || “ပတွဵုနူပြဘာတ်ဝွံ ဂွံစဳရေၚ်ဂဗုတ်ဂလာန်တံဝွံတုဲဂှ် မမိက်ကဵုလာဘညိညဂှ် ပိုဲဟွံကလိဂွံရ။ ပိုဲဟီုပလီုကၠေံအကြာသၟိၚ်တုဲ ကဵုသၟိၚ်ဂစိုတ်ကၠေံရ” အမာတ် စၞာဲတံဂှ်ဂး။ (ဇ—၅၂၈။ အစွောံ။) = “ဗောဓိပရိဗိုဇ် တရားဆုံးဖြတ်သောကာလမှစ၍ ငါတို့သည် တစ်စုံတစ်ခုကိုမျှ မရကုန်။ ငါတို့သည် မင်းအားကုန်းချော၍ ထိုဗောဓိပရိဗိုဇ်ကို သတ်စေအံ့” ဟု စဉ်းလဲသောအမတ်တို့ကြံကုန်၏။ ‘အမှုဂလာန်’ နှင့်အတူတူ။')
,(3042,3,4,'အလုပ်များသည်။ အလုပ်ရှုပ်သည်။ ပလိဗောဓများသည်။',null)
,(3043,3,1,'အမှုအခင်း။ အငြင်းအခုံ။ တရားရုံးနှင့်ဆိုင်သောအမှု။','“အမာတ်ဂမၠိုၚ် ကဵုစဳရေၚ် ဂဗုတ်အမှုမွဲရ။” (ဇ—၂၄၇။ အစွောံ။) = “အမတ်များသည် အမှုအခင်းတစ်ခုကို စီရင်ဆုံးဖြတ်စေ၏။” ‘အမှုဂဗုတ်’ နှင့်အတူတူ။')
,(3044,3,4,'ပစ်လွှတ်သည်။','ဂဗိုတ်ပတိုန် = ပစ်တၚ်သည်။ “လၟသီုမဂ္ဇအ်ဒၟံၚ်ပ္ဍဲသွက် ၜှ် သတ်ချတုဲ ဂဗိုတ်ဖျေံ ဂတမုက်ဗောဓိသတ်(တ္ၜိုၚ်)ရ။” = “မုဆိုးသည် လင့်­ထိုင်လျက် ယမနေ သီးကိုခူး၍ ဘုရားလောင်းဆတ်၏ရှေ့­ ပစ်ချ၏။”')
,(3045,3,1,'အိမ်ခါးဗန်း။',null)
,(3046,3,1,'နဖား။','စင်ဂဗာဲကဵုဂၠဴ = နွားကို နဖားထိုးသည်။ သာတ်ဂဗာဲ = နဖားကြိုးဖြုတ်သည်။ ‘သဗာဲ’ ဟုလည်းရေးသည်။')
,(3047,3,4,'၁။ (ဝမ်းဗိုက်) တင်းသည်။ ပူသည်။ ပြည့်ဖောင်းသည်။','‘ဂၞဴဂဗှ်ေ’ တွင်ရှု။')
,(3047,3,4,'၂။ ပေကျံသည်။ လိမ်းကျံသည်။','“(ထေရ်ဗျုဂှ်) ဒြေပ်လောပ်အာ သ္ၚိဍာ်တရေံသမ်အိုဟ်မွဲ ထလိုၚ်ဗၠုက်စှ်ေအာ ဂၠက်ဂဗှ်ေဒၟံၚ် ပ္ဍဲအသုဘဂှ်ရ။” (ဇ—၁၅၃။ အစွောံ။) (ဂဗှ်ေ = လေတ်) = “ထိုရဟန်း အိုသည် ဆွေးသောအိမ်သာဟောင်းတစ်ခုထဲသို့ ပြေးဝင်သွားသည်ရှိသော် ကြမ်းကျွံ၍ မစင်တွင်း ထဲသို့ ကျသွားပြီး မစင်ဖြင့်လိမ်းကျံလျက် မစင်­နစ်နေ၏။”')
,(3048,3,1,'ထိန်းကျောင်းသူ။','ဂမာစိၚ် = ဆင်ထိန်း။ ဂမာဂၠဴ = နွားကျောင်းသား။ “မာတုဂံါဂှ် ဆဒှ်ဂမာပြေၚ်၊ ဂမာဂၠဴ၊ ဂမာစိၚ်၊ ဂမာချေံ ဆဒှ်မၚ်မွဲဍေံဟွံမာန်ရ။” (ဇ—၂၆၂။ အစွောံ။) = “မတုဂါမမည်သည်ကို ကျွဲထိန်း၊ နွားထိန်း၊ ဆင်ထိန်း၊ မြင်းထိန်းတို့မျှလည်း စောင့်ရှောက်အံ့သောငှာ မတတ်နိုင်ကုန်။”')
,(3050,3,1,'ကလေးထိန်းယောကျာ်း။ အထိန်းတော်ယောကျာ်း။ မိမိငယ်စဉ်ကတည်းက မိမိကို ပြုစုစောင့်ရှောက်ပေးသောအစ်ကို။',null)
,(3051,3,1,'စလောင်းဖုံး။','ဂမဳထၟာဲ = အိုးအဖုံး။ || “ထၟာဲဂှ်ဟွံကတဴ ဂမဳဂှ်ရောၚ်ကတဴ။” = “အိုးကမပူ စလောင်းကပူသည်။” || “(ခ္ဍာ်) ပဝ်စှ်ေဍုန်ပ္ဍဲက္ဍိုပ်ဂၟဳဂှ်တုဲ ၜံက်စဖျုန်တံဂှ်ရ။” (ဇ— ၂၇၄။ အစွောံ။) = “ကျီးသည် ပျံဆင်းလာကာ စလောင်းဖုံးပေါ်­နား၍ အမဲသားတို့ကို စား၏။”')
,(3052,3,1,'‘ဂၟာ်’ ရှု။',null)
,(3053,3,1,'‘ဒမုၚ်ဒလေၚ်’ ရှု။',null)
,(3054,3,1,'‘ဂၟံၚ်’ ရှု။',null)
,(3055,3,4,'‘ဂၟိုၚ်’ ရှု။',null)
,(3056,3,1,'ခြၚ်။','‘ဂၟိတ်’ ရှု။')
,(3057,3,4,'ရိုက်သည်။','‘လမိုတ်’')
,(3057,3,4,'ရိုက်သည်။','‘လၟိုတ်’ ရှု။')
,(3058,3,1,'သမီး၏လင်။ သားမက်။',null)
,(3059,3,1,'ညီမ၏လင်။ နှမ၏လင်။ ယောက်ဖ။',null)
,(3060,3,1,'တစ်အိမ်တည်းမှ သားမက်များ။ မယားညီအစ်ကို။',null)
,(3061,3,1,'မရီး။',null)
,(3062,3,1,'အာစောက်။ (ပါဠိ—ကာကုဒ)',null)
,(3063,3,1,'၁။ ဖန်ခါးသီး။',NULL)
,(3064,3,4,'၂။ သက်လုံ။ အမောခံနိုင်ရည်ရှိမှု။','သက်လုံကောင်းသည်။ အမောခံနိုင်ရည်ရှိသည်။')
,(3065,3,1,'ဆားမြေ။','နွေရာသီ­ ပင်လယ်ကမ်းနားဒေသတွင် ရေခန်းခြောက်သောအခါ ဆားပွင့်များ ဖြူဖွေးစွာဖြစ်ပေါ်နေသောမြေ။')
,(3066,3,3,'‘ခမိဟ်’','‘ခၟိဟ်’ ရှု။')
,(3067,3,1,'‘ခမဳ’ ရှု။',null)
,(3068,3,1,'ဆိုင်း။',null)
,(3069,3,1,'အနာအရှိန်။ အနာအဆိပ်။','ဂယိသရ = အနာရှိန်။ အနာဆိပ်။ || “ဇာဒိသိုၚ်ဂှ် (ဇုတ် ဂၚ်အာကအ်တုဲ ကအ်ဂုဟ်တဴရ။) ဂွံဗၠးနူဂယိဂှ်တုဲ နွံပ္ဍဲကာလမွဲတ္ၚဲ ကိတ်ဂွံပြေၚ်ဂြိုပ်မွဲတုဲ စတဴရ။” (ဇ—၃ဝ၈။ အစွောံ။) = “ခြင်္သေ့၏လည်­ အရိုးသည်ငြိ၏။ လည်သည်ဖူးဖူးရောင်၏။ ခြင်္သေ့သည် အနာမှပျောက်ကင်း၍ တနေ့သ၌­ တခုသောတောကျွဲကို သတ်၍စား၏။”')
,(3070,3,1,'ဆီလိမ်းသည်။ ခေါင်းလိမ်းသည်။','ကၠေၚ်ဂယိ = ခေါင်းလိမ်းဆီ။')
,(3071,3,1,'နံနက်။','ပယာံဂယး = နံနံက်ပိုင်း၊ နံနက်ခင်း။ ပုၚ်ဂယး = နံနက်စာ။')
,(3072,3,1,'နံနက်စောစောအချိန်။',null)
,(3073,3,1,'ကညၚ်ပင်။','ကၠေၚ်ဂယာၚ် = ကညင်ဆီ။')
,(3074,3,1,'ဇနီး (သို့မဟုတ်) ခင်ပွန်း။','သ္ပတၠဂယိုၚ် = အိမ်ထောင်ပြုသည်။ ဒှ်တၠဂယိုၚ်= အိမ်ထောင်ကျသည်။')
,(3075,3,1,'အသက်မွေးမှု။ အသက်မွေးဝမ်းကြောင်း။','“ကောန်ညးဒိုက်ဂတ်တအ်ဂှ် ဟိုတ်နူဂယိုၚ်လမျီုမဒိုက်တုဲ ဒးလိၚ်ကၠောန်ကာညးအိုတ်ရ။” = “ဆင်းရဲသားတို့သည် အသက်မွေးမှုကျပ် တည်းသဖြင့် သူတစ်ပါးထံတွင် သူရင်းငှားလုပ်ကြရသည်။”')
,(3075,3,4,'အသက်မွေးသည်။ အသက်မွေးဝမ်းကြောင်းသည်။','“ဗမၞးမဗောဓိသတ်ဂှ် ဇိက်စဗ္ၚ ဂယိုၚ်လမျီုရ။” (ဇ—၂၁၁။ အစွောံ။) = “ဘုရားလောင်း၏အဖပုဏ္ဏားသည် လယ်လုပ်ခြင်းဖြင့် အသက်မွေး၏။” || “လၟမွဲဂှ် လောပ်အာဂြိုပ် ပံါဂွံဂစေံဒဂိုတ်မဂၠိုၚ်တုဲ ကြိုၚ်လဝ်တုဲ သွံစဂယိုၚ်လမျီုရ။” (ဇ—၁၁၈။ အစွောံ။) = “တစ်ယောက်သောမုဆိုးသည် တောသို့ဝင်၍ များစွာသော ငုံးငှက်တို့ကိုဖမ်းပြီးလျှင် လှောင်ထားကာ ရောင်း၍အသက်မွေး၏။” ‘ဂမျိုၚ်လမျီု’ ဟုလည်း အနည်းအားဖြင့်တွေ့ရသည်။')
,(3076,3,4,'ခါသည်။','‘လယှ်’ ရှု။')
,(3077,3,4,'သီဆိုသည်။','‘ဒယှ်ေ’ ရှု။')
,(3078,3,1,'အၚ်တုံ။','‘ဇရ’')
,(3078,3,1,'အၚ်တုံ။','‘ဒြ’ ရှု။')
,(3079,3,1,'စဉ့်အိုး။','‘ဇရဳ’ ရှု။')
,(3080,3,10,'(န) နှစ်မတြာရှည်ကြာသောအသံ။ ဂရု။',null)
,(3081,3,10,'(န) အလေးအမြတ်ပြုခြင်း။',null)
,(3082,3,11,'(န) အလေးပြုအပ်သည်ဖြစ်၍ မခွဲဝေအပ်သောပစ္စည်း။ ဂရုဘဏ်။ (ပါဠိ—ဂရုဘဏ္ဍ)','‘လဟုဘဏ်’ လည်းရှု။')
,(3083,3,4,'ဆူပူသည်။','‘လရုလစာ်’ ရှု။')
,(3084,3,4,'ပျက်ပြားစေသည်။ ဖျက်သည်။','“ဂရူထောံဝိုၚ်။” = “ဝိုင်းကိုပျက်စေသည်။ ဝိုင်းကို ဖျက်သည်။”')
,(3085,3,1,'စွန်ကစားသောရစ်လုံး။',null)
,(3086,3,1,'(အပင်) အထီး။ အဖို။','ကစ္စဳဂရဲ = သၚ်္ဘောသီးအဖိုပင်။')
,(3087,3,1,'တွန်ခြင်း။ တွန်သံ။','“သဝ်ရဝကာ်မွဲ — ဍုန်ဒၟံၚ်ပ္ဍဲတဏအ်ဂှ်တုဲ ဗရုဂရဴမဇၞော်မသၠုၚ် ဟေၚ် နရိုအ်ဂြဴတဴလၟိုန်။” (ဇ—၁၁၇။ အစွောံ။) = “တစ်ခုသောခါငှက်သည် ထိုတောင်ပို့­နား နေလျက် ကျယ်လောင်သောတွန်သံဖြင့် အမြဲတစေ ငိုမြည်တွန်ကျူး၏။” || ‘ဂြဴ’ (ကြိ) လည်းရှု။')
,(3088,3,1,'၁။ ခေါင်းဖြီးသောဘီး။','‘ခရး’ ဟုလည်း ရေးသည်။')
,(3088,3,1,'၂။ ထွန်ခြစ်။ ထွန်သွား။',null)
,(3088,3,9,'(ငှက်ပျောသီး)အဖီး ကိုရေတွက်ရာတွင် သုံးသောစကားလုံး။၊','ဗြာတ်ၜါဂရး = ငှက်ပျောသီးနှစ်ဖီး။')
,(3089,3,1,'ဘီးကုပ်။ ဆံပင်ထိန်းရန် စိုက်ရသောဘီးခုံး။',null)
,(3090,3,1,'ဘီးစိပ်။',null)
,(3091,3,1,'ချည်ခင်ဖြီးဘီး။',null)
,(3092,3,1,'ဝက်မှင်ဘီး။',null)
,(3093,3,1,'ဘီးဆံပတ်ဘီး။',null)
,(3094,3,4,'အလျင်လိုသည်၊ အလျင်စလိုလုပ်သည်။','“ညံၚ်ဂွံစိုပ်ပြဟ်ဂှ် ညးဂရေက်ကွာ်အာရ။” = “အမြန်ရောက်ရန် သူအလျင်စလိုလျှောက်သွားသည်။”')
,(3095,3,4,'တင်းကျပ်စွာညှစ်သည်။','“ခ္ဍာ်တယောဝ်ဏာကအ်ဗက် ‘စောပ်’ ဂတာံဂှ် သ္ကေပ်ဂွံ ကၠေံရ။ ဂတာံဂရေက်ကအ်ခ္ဍာ် ဗြုဟွံတိတ်ရ။” (ဇ—၃၈၉။ အစွောံ။) = “ပုစွန်သည် ညှပ်ဖြင့် ညှပ်သကဲ့သို့ ကျီး၏လည်­ လက်မဖြင့်မြဲစွာညှပ်၏။ ပုစွန်သည် ကျီး၏လည်ကို တင်းကျပ်စွာ ညှစ်ထားရာ ကျီးသည်မအော်နိုင်။” || “ဂတာံတၠၚာၚ်ဂှ် သ္ကေပ်ဂရေက်လဝ်ကအ်အဲတုဲရ။ တၠအဲ ကၠုၚ်ပြာ်လမျီုအဲပြဟ်ညိ” ခ္ဍာ်ဂးကဵုဇြုံရ။ (ဇ—၃၈၉။ အစွောံ။) = “ပုစွန်သည် လက်မဖြင့် ငါ၏လည်ကို မြဲစွာညှပ်၍ တင်းကျပ်စွာညှစ်ထားပြီ။ သင်သည်လာ၍ ငါ့အသက်ကို ကယ်ပါလော့” ဟု ကျီးသည်မြွေအားဆို၏။')
,(3096,3,5,'အလောတကြီး။ အလျင်စလို။ အဆောတလျင်။ (ပါဠိ— အစ္စေကံ)',null)
,(3097,3,1,'ချောက်ကမ်းပါး။ တောင်ကြား။ လျှိုမြောၚ်။','ဂရော်ဒဵု = တောင်ကြား။ (ပါဠိ—ဂဗ္ဘရ)')
,(3098,3,4,'လှုပ်သည်။ ခါသည်။','‘ဒရိုက်’ ဟုလည်း ရေးထုံးရှိသည်။')
,(3099,3,4,'ခေါင်းခါသည်။ ငြင်းပယ်သည်။',null)
,(3100,3,4,'လှုပ်ခါသည်။ လှုပ်ရှားသည်။','‘ဒရိုက်ဒရာၚ်’ ဟုလည်း ရေးထုံးရှိသည်။ || “ခမဳဍောတ်အဇိတထေရ် မသ္ဂောံဒှ်ကျာ်အရဳယျဂတဝွံရောၚ်ဂးတုဲ တိသုန္ဓရဳချဳသရပ်ဒဇပ်ဇတဝ် ဂရိုက် ဂရာၚ်တဴရ။” (အဓါန်မသုန်။ အစွောံ။) = “အဇိတမည်သောရဟန်းငယ်သည် ရှေ့တွင် အရိမေတ္တေယမည်သော ဘုရားဖြစ်ရလတ္တံ့ဟု မဟာပထဝီမြေကြီးသည် သိမ့်သိမ့်တုန်လျက် လှုပ်ရှားလေ၏။”')
,(3100,3,4,'လှုပ်ခါသည်။ လှုပ်ရှားသည်။','“ထေရ်မုဂ္ဂလာန် ကလာၚ်တိုန်အာ လတူအကာသတုဲ နကဵုလပုဟ်ဇိုၚ်ဂှ် ဆတိသၟဝ်ပြာ သာဒ်ဂှ် ကသဳတုဲ ဒဵုကဵုဍာ်ဂတာသၟဝ် မဒုၚ်တိတေံဂှ် ချဳဂရိုက်ဂရာၚ် ခမဳတံဂှ်ဖေက်တုဲ တိတ်အာမ္ၚး ပြာသာဒ်ဂှ်ရ။” (ဇ—၂၉၉။ အစွောံ။) = “အရှင်မောဂ္ဂလာန်မထေရ်သည် ကောင်းကင်သို့ ပျံတက်တော်မူ၍ ခြေမဖြင့် ပြသာဒ်ထုပိကာကိုခတ်၍ ရေအဆုံးရှိသည်တိုင်အောင် ပြာသာဒ်ကို လှုပ်စေ၏။ ထိုရဟန်းတို့သည် သေဘေးဖြင့်ကြောက်ကုန်ရကား ထွက်၍ အပ­တည်ကုန်၏။” (ညောင်ကန်)')
,(3101,3,4,'၁။ တောင်းရမ်းသည်။','ဂရၚ်စ = တောင်းရမ်းစားသည် || ရဲဂရၚ်စ = သူတောင်းစား။')
,(3101,3,4,'၂။ အသိပေးသည်။ နှိုးဆော်သည်။','“သီုညးဂမၠိုၚ်ဂှ် ဂရၚ်သၟဟ်သၟန်တုဲ ပ္ကောံဓရီုသရောပ် ဖဍောပ်အပေါတ်ဒါန်အိုတ်တုဲ—။” (ဇ—၁၈ဝ။ အစွောံ။) = “လူအပေါင်းတို့သည် အချင်းချင်းနှိုး ဆော်ညီညွတ်ကြပြီးလျှင် လှူဖွယ်ဝတ္ထုတို့ကို စုစည်း၍ အသင့်ပြင်ဆင်ကြကုန်၏။”')
,(3102,3,4,'အသိပေးသည်။ ကြားသိစေသည်။ လျှောက်တၚ်သည်။ ကြားလျှောက်သည်။','“ဒဒှ် ဂှ် ခမဳဂမၠိုၚ် ဂရၚ်ပ္တီကျာ်တြဲရ။” = “ထိုအကြောင်းကို ရဟန်းများသည် မြတ်စွာဘုရားအား ကြားလျှောက်ကုန်၏။” || “ခ္ဍာ်သုမုခဂှ် ပ္ကောံကေတ်ခ္ဍာ်ဂမၠိုၚ်တုဲ ဒဒှ်အိုဿီုဂှ် ဂရၚ်ပ္တီခ္ဍာ်ဂမၠိုၚ်တုဲ —။” (ဇ—၂၉၂။ အစွောံ။) = “သုမုခကျီးသည် ကျီးအပေါင်းတို့ကို စုရုံးစေ၍ ဖြစ်ကြောင်းအလုံးစုံကို ကျီးအပေါင်းတို့အား အသိပေး၏။”')
,(3103,3,4,'ကြေညာသည်။ ကြားသိစေသည်။','“ပ္ဍဲဍုၚ်သာရဝှ်ဂှ် သ္ဘၚ်မသုၚ်သုရာဂှ် ညးဂရၚ် ပၟိၚ်ဂွံမိၚ်တုဲ ဗြဴမသုန်ကၠံဂှ် သွက်တၠသ္ၚိဍေံတံဂှ် သုရာဇမ္ကာတ်ဂှ် ဍေံတံစဳရေၚ်အိုတ်ရ။” (ဇ—၅၁၂။ အစွောံ။) = “သာဝတ္ထိပြည်­ သေသောက်ပွဲသဘၚ် ကြေညာသည်ကိုကြား၍ ထိုငါးရာကုန်သော မိန်းမတို့သည်လည်း မိမိတို့လင်အား ထက်စွာသောသုရာကို စီရင်ကုန်၏။”')
,(3104,3,4,'ကြေညာသည်။ (သတင်းစကားစသည်ကို အများကြားသိအောင်လုပ်သည်။)','“ဒှ်ရ သာ်ဂှ် မၞးတအ်အာဂရၚ်ဟီုအလုံဍုၚ်ညိ” သၟိၚ်ဂး။ (ဇ—၂၈၅။ အစွောံ။) = “ထိုသို့တပြီးကား သင်တို့သည် မြို့အလုံးသို့ ကြေညာကြကုန်လော့” ဟုမင်းသည်ဆို၏။')
,(3105,3,4,'လှုပ်သည်။ ဘေးဘယ်ညာ လှုပ်အောင်လုပ်သည်။','“(ဂဒိုအ်ဂှ်) ဍေံကဵုထေရ် တိုန်က္ဍိုက်ဂၠုၚ်တုဲ ဗွဲတမ္ၚူဂှ် ဍေံဟွံစၠောအ် ဗွဲသၟဝ်သၞေဟ်ဂှ် ဍေံဖျေံဏာတုဲ ဍေံဂရာၚ်ဂၠုၚ်တုဲ ဗ ဗေၚ်သ္ၚာထေရ် တ္ဍေက်ဒဇက်တဴရ။” (၅၅ဝ။ ဇ—၃၇၆။ ဒု—၃၆၂။ အစွောံ။) = “ကူးတို့သည်သည် — မထေရ်ကို လှေသို့တၚ်၍ ဖြောင့်စွာမသွားမူ၍ လှေကို အောက်သို့ဆောင်၍ မြစ်­လှေကိုလှုပ်၍ ထိုရဟန်း၏သပိတ်သၚ်္ကန်းကို စွတ်စိုစေ(၏။)” (၅၅ဝ။ တ—၁၁၆။ ညောင်ကန်။) ‘ချဳဂရာၚ်’၊ ‘ဂရိုက်ဂရာၚ်’ လည်းရှု။')
,(3106,3,4,'မခိုၚ်မခန့်ဖြစ်သည်။ ပုံမှန်မကျဖြစ်သည်။',null)
,(3107,3,1,'ရယ်မောခြင်း။ အရယ်အမော။','“နဂရိုၚ်မဇၞော်ဂှ် ဂြိုၚ်တိုန်ရ။” (ဇ—၁၈။ အစွောံ။) = “သည်းစွာသောရယ်ခြင်းကို ရယ်သည်။” || ပဂရိုၚ် = ပျက်ရယ်ပြုသည်။ || က္တဵုဂရိုၚ် = ရယ် မောစရာလုပ်သည်။ တဟားဟားရယ်စေသည်။ || ‘ဂြိုၚ်’ (ကြိ) လည်းရှု။')
,(3108,3,1,'အရယ်အပြုံး။ ပြုံးရယ်ခြင်း။','“သၟတ်ဗြဴဝုတ်ဂှ် မၞုံကဵုဂရိုၚ်ဂအီကျာ်သြဳရ။” = “ထို မိန်းမပျိုသည် ကျက်သရေရှိသော အရယ်အပြုံးရှိ၏။” || “(ဒြာဲဂှ် ဗၠးနူတဲလၟတုဲ) ဍေံကၠုၚ်က္တဵုဗဒှ် ဂရိုၚ်ဂအီမိရ။” (ဇ—၁၆။ အစွောံ။) = “ထိုသမင်သည် မုဆိုးလက်မှလွတ်၍ မိခင်ထံလာ၍ မိခင်အား ရွှင်ပြုံးစေ၏။” || “(ဗြဴစရာဲဍုၚ်ဂှ်) က္တဵုဗဒှ်ဂရိုၚ်ဂအီၚေက်လပံက်အာ။” (ဇ—၁၁၈။ အစွောံ။) = “ထိုပြည့်တန်ဆာမသည် အရယ်အပြုံးကို ဖြစ်စေသည်ရှိသော် သွားတို့ပေါ်ကုန်၏။” || “ကလော်ဗြဴတံဂှ် နဂရိုၚ်ဂအီစၞာဲဗြဴစှ်ပန်သာ်ဂှ် ဍေံဟီုလှေအ်လှန် (တြုံညးဗၞိက်တံဂှ်ရ။)” (ဇ—၁၉၆။ အစွောံ။) = “ဘီလူးမတို့သည် မိန်းမတို့၏အရယ်အပြုံးနှင့် တစ်ဆဲ့လေးဖြာသော မိန်းမမာယာတို့ဖြင့် ကုန်သည်ယောကျာ်းတို့ကို မြှူဆွယ်ဖြားယောင်းကုန်၏။”')
,(3109,3,1,'ပြက်ရယ်ပြုခြင်း။ ပြက်ရယ်ပြုသောစကား။','သၟိၚ်ဂှ်တုန် ဂွံလဝ်ကောန်ဂစေံပိဂှ်တုဲ “ကောန်တြုံအဲ ကောန်ဗြဴအဲ” ဂးဒၟံၚ်လၟိုန်ဂှ်ရ အမာတ်တံကၠုၚ်ကောံမွဲဟာန်တုဲ ဟီုစတဴဂရိုၚ်စရဵု အိုတ်ရ။ (ဇ—၅၂၁။ အစွောံ။) = မင်းသည် ငှက်သုံးကောင်ကိုရထားပြီး “ငါ့သားတော် ငါ့သမီးတော်” ဟု အမြဲတမ်းခေါ်ဆိုနေရာ အမတ်တို့လာရောက်စုဝေးစဉ် မင်းအား ပြက်ရယ်ပြုကြ ကုန်၏။ ‘ပဂရိုၚ်စရဵု’ (ကြိ) လည်းရှု။')
,(3110,3,1,'လှောင်ပြောင်ကျီစယ်ခြင်း။ ရယ်စရာသဘော အပျော်သဘော ပြောဆို ကျီစယ်ခြင်း။','(မှတ်ချက်။ ‘ဂရိုၚ်’သည် ‘ဂြိုၚ်’ မှပွားလာသောဝေါဟာရဖြစ်၍ ‘ပွေၚ်’သည် ‘ဝေၚ်’ မှပွားလာသောဝေါဟာရဖြစ်သည်။ ‘ဂရိုၚ်ပွေၚ်’ သည် (န) ဖြစ်၍ ‘ဂြိုၚ်ဝေၚ်’ (ကြိ) မှပွား လာခြင်းဖြစ်သည်။)')
,(3111,3,4,'လှောင်ပြောင်ကျီစယ်သည်။','“(ခမဳဂှ် ရာံဂွံတြဴဝါရ၊ ကြဴဝွံပခမဳပၠန်ဂှ်ရ) ခမဳမ ဒှ်သဟာဲတံဂှ် သၟိက်ဟီုဂရိုၚ်ပွေၚ်တုဲ ‘တၠအဲဟွံချပ်ရာံဏီဟာ’ သၟာန်ခမဳဂှ်ရ။” (ဇ—၇ဝ။ အစွောံ။) = “ထိုရဟန်းသည် ခြောက်ကြိမ်တိုင်အောင် လူဝတ်လဲခဲ့၏။ ထိုနောက်တွင် ရဟန်းပြုပြန်သဖြင့် အဆွေခင်ပွန်းဖြစ်ကုန်သော ရဟန်းတို့က ထိုရဟန်းအား အပျော်သဘော ကျီစယ်လှောင်ပြောင် လို၍ ‘ငါ့ရှင်၊ ဘယ်တော့လူထွက်ဦးမှာလဲ’ ဟုမေးကြကုန်၏။”')
,(3112,3,4,'ရယ်ရွှၚ်ကစားစရာပြုသည်။','“သၟိၚ်ပပွေၚ်ဂရိုၚ်ကဵု(ကၞုဲဂှ်—။)” (ဇ—၂၁၉။ အစွောံ။) = “မင်းသည် ထိုမျောက်ကို ရယ်ရွှၚ်ကစားစရာ အပျော်မျောက်ပြု၏။”')
,(3113,3,4,'ပွတ်တိုက်သည်။ ခြစ်သည်။ (ပါဠိ— ပရိဃံသတိ','ဥဂ္ဃံသတိ)')
,(3114,3,4,'၁။ ပွတ်တိုက်သည်။ ခြစ်သည်။ (ပါဠိ—ပရိဃံသတိ)။',NULL)
,(3114,3,4,'၂။ တိုးဝှေ့သည်။ (ပါဠိ—အနုပခဇ္ဇ)',NULL)
,(3114,3,4,'၃။ ခိုက်ရန်ဖြစ်သည်။','“သတ္တံမွဲမွဲ ဒၟံၚ်မွဲဇကုဂှ် ဟွံဂွံဂရိတ်ခတ် ဟွံဂွံ ထဍဳလယတ်ကဵုရၚ်သ္ကံရ၊ ဟွံဂွံဒှ်ဝါတ်ဂါတ်ကဵုရၚ်သ္ကံရ။ ညးၜါညးပိကောံရၚ်သ္ကံတုဲ ဒးဒှ်တဴဝါတ်ဂါတ် ကေုာံရၚ်သ္ကံရ။” (ဇ—၄ဝ၈။ အစွောံ။) = “သတ္တဝါတို့သည် တစ်ကိုယ်တည်းနေသော် အချင်းချင်းမထိတွေ့ မတိုက်ခတ် အငြင်းအခုံမဖြစ်။ နှစ်ဦးသုံးဦးဆုံသောအခါ အချင်းချင်းငြင်းခုံခိုက်ရန် ဖြစ်ကြရကုန်၏။”')
,(3115,3,4,'ပွတ်တိုက်သည်။ ထိခိုက်သည်။',null)
,(3116,3,3,'(စကား၊ အဆို) ကြမ်းကြုတ်သော။ ရုန့်ရင်းသော။','“ဟာဲသမတ်၊ ဂလာန်ဂ ရိတ်နက် မသ္ကာတ်မြဟ်မရာန်သကိုတ်ဂှ် တၠအဲမဟီုသွံ။” (ဇ—၄၄၆။ အစွောံ။) = “ချစ်သား၊ သင်ချစ်သားသည် ရုန့်ရင်းကြမ်းကြုတ်ကုန်သော စကားတို့ဖြင့် နှိပ်စက်လွှမ်းမိုးလျက် ထိပါး၍ ငါ့ကိုဆိုဘိ၏။” (ညောင်ကန်)')
,(3117,3,4,'ပွတ်တိုက်သည်။ ထိခိုက်သည်။','“ကၞာၚ်ဆုၜါဂှ် ဒးကျာတုဲ ဂရိတ်ဗုတ်ရၚ်သ္ကံရ။” (ဇ—၃၆။ အစွောံ။) = “သစ်ခက်နှစ်ခုတို့သည် လေထိ၍ အချင်းချင်းပွတ်တိုက်ကြကုန်၏။”')
,(3118,3,4,'ပွန်းပဲ့သည်။',null)
,(3119,3,1,'အဖုံး။ အစွပ်။','‘ဂြောပ်’ (ကြိ) လည်းရှု။')
,(3126,3,1,'အရှက်ကိုဖုံးရန် အဝတ်အရုံ။','“ဂရောပ်လတက်ဝွံ အဲဍိက်အာတ်ဟွံသေၚ်။ ဂရောပ်လတက် မတွံဂးတလသ္ၚိ အဲဍိက်မအာတ်ရောၚ်” ဗြဴဂှ်ဂး။ (ဇ—၆၇။ အစွောံ။) = “ဤ အဝတ်အရုံကို အကျွန်ုပ်တောင်းသည်မဟုတ်ပါ။ လင်တည်းဟူသော အဝတ်အရုံကိုသာ အကျွန်ုပ် တောင်းပါ၏” ဟုထိုမိန်းမဆို၏။')
,(3127,3,1,'အကာအရံ။ စောင်းရန်း။',null)
,(3128,3,1,'အနား၊ အကွပ်။',null)
,(3129,3,1,'(ကြက်ငှက်စသည်၏) အတက်။','ဂရှ်စာၚ်အုက် = ကြက်ဖအတက်။')
,(3130,3,3,'အကျည်းတန်သော။ အရုပ်ဆိုးသော။','“မဏ္ဍဗျကုမ္မာ ပ္ဍဲမမၠာ်မွဲတဴဂှ် ညာတ်ကေတ်မာ တၚ်္ဂ မၞုံရုပ်ဂရှ်ဂပှ် မတုပ်တဴညံၚ်ရဴကလော်အပိၚ်သာတ် —။” (ဇ—၄၉၇။ အစွောံ။) = “မဏ္ဍဗျ ကုမ္မာသည် ကြည့်လတ်သည်ရှိသော် မြေဘုတ်ဘီးလူးကဲ့သို့ အကျည်းတန်အရုပ်ဆိုးသော မာတၚ်္ဂ ကိုမြင်၏။”')
,(3131,3,1,'ကဲ့ရဲ့ခြင်း။','“ပွအနေသနၜါစှ်ောမွဲဝွံဂှ် မဒှ်က္ဍုဟ်ကျာ်အရှန်ပစ္စေဂဗုတ်တံရောၚ်။ ဒှ်ဂ ရိုဟ်ကျာ်အရှန်ပစ္စေဂဗုတ်တံရောၚ်။ ” (ဇ—၁၇၉။ အစွောံ။) = “နှစ်ဆဲ့တစ်ပါးအပြားရှိသောအ နေသနအမှုသည် ဘုရား၊ ရဟန္တာ၊ ပစ္စေကဗုဒ္ဓါတို့၏ စက်ဆုပ်ရာဖြစ်၏။ — ကဲ့ရဲ့ရာဖြစ်၏။”')
,(3131,3,4,'ကဲ့ရဲ့သည်။','“လောကဓဝ်ဒစာံပြကာ မပ္တံညးထိုင်သးဇကုကီု ညးဂရိုဟ်ဇကုကီု ဒုၚ်ဒဝ် ကဵုမာန်ညိ။” = “မိမိအားချီးမွမ်းခြင်း ကဲ့ရဲ့ခြင်းအစရှိသော လောကဓံတရားကို ခံနိုင်ရည်ရှိပါစေ။” || “ဇန်တံညးဂမၠိုၚ်ဂှ် ဍေံဂရိုဟ်အဲကီု ဍေံဗျိပၠုတ်အဲကီု အဲသ္ဂောံတီညိခိုဟ်ရောၚ်” သၟိၚ်ချပ်။ (ဇ—၁၅၁။ အစွောံ။) = “လူအပေါင်းတို့သည် ငါ့ကို ကဲ့ရဲ့ကြကုန်သလား၊ ငါ့ကို အပြစ်ဆိုရှုတ် ချကြကုန်သလား သိရလျှင်ကောင်းမည်” ဟုမင်းကြံ၏။')
,(3132,3,4,'ကဲ့ရဲ့ရှုတ်ချသည်။','“မၞိဟ်လက်ဖာဂရိုဟ်ဒနာညးတံဂှ်ရောၚ် ဍေံထိုင်သး။” (ဇ— ၄၇၃။ အစွောံ။) = “သူတစ်ပါးအား ဆဲရေးရှုတ်ချသောလူကိုသာလျှင် သူချီးမွမ်း၏။”')
,(3133,3,1,'အရေအတွက်မှတ်ရာတွင် သုံးရသောနှီးပြား၊ တုတ်ချောင်း၊ စပါးလုံးစသည်။ တာလီ။ ဂရို့။ အမှတ်။ (မြန်မာဝေါဟာရ ‘ဂရို့’သည် မွန်ဝေါဟာရ ‘ဂရောအ်’','‘ဂရိုအ်’ မှ ဆင်းသက်လာနိုင်ဖွယ်ရှိသည်။) || “ပ္ဍဲဗဝဝ်သြောံမဟွံဂွံသူဏီဂှ် မသြောံဂှ်ဂိုၚ်ကေတ်တုဲ မသြောံပဂ ရောအ်ရ။” (ဇ—၂၇၆။ အစွောံ။) = “မခြင်ရသေးသောစပါးပုံမှ စပါးစေ့တို့ကိုယူ၍ (မှတ်သား ရာတွင်သုံးရန်) ဂရို့လုပ်၏။”')
,(3134,3,1,'ကုလားလူမျိုး။',null)
,(3135,3,1,'တမီလူမျိုး။ တမီကုလား။',null)
,(3136,3,1,'ဂျာဗားကုလား။',null)
,(3137,3,1,'ကုလားဖြူလူမျိုး။ မျက်နှာဖြူလူမျိုး။',null)
,(3138,3,1,'အာရပ်လူမျိုး။',null)
,(3139,3,4,'ပူဇော်ပသသည်။',null)
,(3140,3,4,'မြေထဲ၌နှစ်မြှပ်သည်။ နှစ်သွင်းသည်။', '“ညံၚ်ပါဒလက်သန် (ကျာ်တြဲ) မလိုန်ဂလက်လလဝ် တဆိပ်ဂၠးဂတာဇိုၚ် ပ္ဍဲတၟံဗိုတ်တမြံၚ်ကီု။” (ဇ-ဝိဓုရ။ အစွောံ) = “မြတ်စွာဘုရား၏ပါဒလက္ခဏာ ခြေရာတော်ကို မာသောစိန်ကျောက်အပြင်၌ နင်းနှစ်၍ တံဆိပ်ခတ်နှိပ်ထားတော်မူဘိသကဲ့သို့” || “တၟံ (၄) ဂတှေ် ဂလက်ဖျေံလဝ် ဗဒါဲပန်ဒိုဟ်ကတိုၚ်” (ရာဇာဝံသသံခိပ်။ အစွောံ) = “ကျောက်ချပ် (၄) ချပ်တို့ကို တွင်း၏လေးဘက်ဝန်းကျင်၌ နှစ်သွင်း၍မြှပ်နေစေ၏” || ‘ဂၠံက်’ (ကြိ) လည်းရှု။')
,(3141,3,4,'၁။ ဖုံးကွယ်ဝှက်ထားသည်။','“(လၟဂှ် တၞဟ်နဂစိုတ်စိၚ်) ဍေံဂလုက်လဝ်ဗၞောဟ် ဍေံ သၠောံသ္ၚာ ဍေံစုတ်အထုပ်တုဲ ဍေံဂ္ဇအ်သ္ၚဳဒၟံၚ်ရ။” (ဇ—၂၂၁။ အစွောံ။) = “ထိုမုဆိုးသည် ဆင်တို့ ကိုသတ်ရန် လှံကိုကွယ်ဝှက်ထားပြီးလျှင် သၚ်္ကန်းကိုခြုံ၍ ဦးထုပ်ကိုစွပ်၍ ငြိမ်သက်စွာထိုင်နေ၏။”')
,(3141,3,4,'၂။ ဆိုက်သည်။ ဦးလှည့်ရပ်တည်သည်။','“ကၠဵုဂြိုပ်မွဲဂှ် ပၟတ်ဂြိုပ်တူတုဲ တၞဟ်နဒဴပၟတ် ဂြိုပ်ဟွံမာန်တုဲ ပ္ဍဲတၞံဆုမွဲ ဂလုက်လဝ်က္ဍိုပ်တုဲ တန်ဒၟံၚ်ရ။” (ဇ—၁၂၉။ အစွောံ။) = “တခုသော မြေခွေးသည် တောမီးလောင်သည်ရှိသော် ပြေးအံ့သောငှာ မတတ်နိုင်သည်ဖြစ်၍ တခုသောသစ်ပင်­ ဦးခေါင်းကိုဆိုက်၍ နေ၏။” (ညောင်ကန်)')
,(3143,3,4,'မီးခိုးတိုက်သည်။ မှိုင်းတိုက်သည်။',null)
,(3144,3,4,'ရှည်အောင်လုပ်သည်။','‘ဂၠိၚ်’ (ကြိ) နှင့်နှိုင်းယှဉ်။')
,(3145,3,4,'အချိန်ဆွဲသည်။ ရက်ရွှေ့ဆိုင်းသည်။ နှောင့်နှေးစေသည်။','“ယးဂတတေံ နက်သတ်မဆာဲရောၚ်ဂးတုဲ ဂလိၚ်ကၠေံကာလ—။” (ဇ—၄၉။ အစွောံ။) = “မ နက်ဖြန်ခါ နက္ခတ်ကောင်းလတ္တံ့ဟုဆိုကာ အချိန်ဆွဲသည်။” ‘ဇလိၚ်တ္ၚဲ’၊ ‘ဇလိၚ်ကာလ’ နှင့်အတူတူ။')
,(3146,3,4,'ယက်ကန်းချည်ရှည်သည်။',null)
,(3147,3,1,'ထမ်းပိုး။','‘ဂၠေၚ်’ (ကြိ) နှင့်နှိုင်းယှဉ်။')
,(3148,3,1,'တံချူ။','‘ဂၠောၚ်’ (ကြိ) နှင့်နှိုင်းယှဉ်။')
,(3149,3,4,'များစေသည်၊ များအောင်လုပ်သည်။','“သွက်ကၟုဲဂွံစ ဂလိုၚ်လဝ်ပုၚ်တုဲရ” = “ဧည့်သည်စားရန်အတွက် အပိုထမင်းချက်ထားပြီးပြီ။”')
,(3150,3,4,'ဈေးမြှင့်သည်။ ဈေးနှုန်းမြှင့်တင်သည်။',null)
,(3151,3,5,'သည်လောက်တောင်မှ။ ဤလောက်တောင်မှ။','“ဗြဴဝွံ အဲပလဝ်ဂုန်ကဵုဍေံဂှ် ဂလိုၚ်ဏအ် ဍေံပဘဲကဵုအဲရောၚ်သွံ။” = “ဤမိန်းမသည် ငါကျေးဇူးပြုထားသလောက် ဤမျှလောက်တောင် ငါ့အား အန္တရာယ်ပြုရက်ပါလား။”')
,(3152,3,4,'စကားများသည်။','“ဂလာန်မဒးဗၞတ်ဂှ် ဟီုညိ၊ ဟွံဂပ်ဂဝ်ဂလိုၚ်ပါၚ်ရ။” = “စကားပြောဆိုရာ­ စကားပမာဏကို သိပါစေ၊ စကားမများသင့်ပါ။”')
,(3153,3,4,'အသားကိုတိုးစေသည်။ ဆူဖြိုးစေသည်။','“ဍေံဏအ်မွဲ စတုဲတိက် ဆဂလိုၚ်ဝေၚ် ဖျုန်သၟးရ။” = “ဤသူတစ်ယောက်ဟာ စားပြီးအိပ်လိုက်နှင့် အသားတိုးစေရုံ (ခန္ဓာကိုယ်ဆူဖြိုး စေရုံ)မျှသာဖြစ်သည်။”')
,(3154,3,4,'မိမိနောက်လိုက်အင်အား များအောင်ပြုသည်။ အခြံအရံများအောင်လုပ်သည်။ မိမိအလိုသို့ပါအောင် စည်းရုံးသိမ်းသွင်းသည်။','“ယွံကောန်သၟိၚ်၊ မၞိဟ်ဒၞာဲဍေံစဳကၠး ဍေံတီဂုန်ညး ဍေံလေပ်ခၠေဝ်ဂုန်ညးတံဂှ် ဗစဖာပ်လှေံလှန်လဝ်ရ၊ ဂလိုၚ်လဝ်ဗော်သွးရ” အစာဂး။ (၅၅ဝ။ ဇ— ၄၆၂။ ၇—၁၂၉။ အစွောံ။) = “အရှင်မင်းသား၊ လိမ္မာရေးခြားရှိကုန်သော ကျေးဇူးသိကုန်သော ကျေးဇူးဆပ်တတ်ကုန်သောလူများကို ကျွေးမွေးစည်းရုံးထားပါလော့၊ မိမိအခြံအရံ ဘက်တော် သားတို့ကို အင်အားများအောင် လုပ်ထားပါလော့” ဟုဆရာဆို၏။')
,(3155,3,5,'ဘယ်လောက်၊ အဘယ်မျှလောက်။','“ကေတ်ဂလိုၚ်လဵုရော။”= “ဘယ်လောက် ယူမည်နည်း။”')
