,(3164,3,1,'မမှန်သောစကား။ ချွတ်ယွင်းသောစကား။',null)
,(3165,3,1,'ကျန်းမာချမ်းသာကြောင်း နှုတ်ခွန်းဆက်မေးမြန်းသောစကား။',null)
,(3166,3,1,'ဆုံးမစကား။ သြဝါဒစကား။',null)
,(3167,3,1,'တောင်းပန်သောစကား။',null)
,(3168,3,1,'အပြန်အလှန်ပြောဆိုသောစကား။',null)
,(3169,3,1,'၁။ ရှေးလူကြီးသူမများ၏ ဆိုရိုးစကား။',NULL)
,(3169,3,1,'၂။ အနှစ်သာရမရှိသော ပေါက်ကရစကား။','“ဂလာန်ပေါရဏာံပေါရဒံါ မပ္တံသဳဒါဟနုမာန်” = “သီဒါဟနုမာန်အစရှိသည့် အနှစ်သာရမရှိသောစကား။”')
